INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ba14868f-a04e-4fb4-ad1e-91b39e65434a', 'Check the required plugin states', 'Query each required plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.358724', '2026-10-07 05:11:12.358725');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('85ba1086-3ba6-445b-9102-fffdb7c753ae', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.358949', '2026-10-07 05:11:12.358950');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8ac8ff4d-f3b7-425a-ad43-a6253698e8f1', 'Build the MP4 player test URL', 'Combine the configured MP4 source URL, selected codec/player, execution identifiers, logging information, pause and play operations, and type: "mp4" into the unified player test URL.', 'A complete test URL should be generated for the selected MP4 player.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.359913', '2026-10-07 05:11:12.359913');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5223f53c-41e4-40b0-99af-522e53af6b2f', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value using {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated MP4 player test URL>"}}.', 'The MP4 player URL should be stored successfully in PersistentStore.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.360161', '2026-10-07 05:11:12.360161');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dda83127-9a29-4d8c-87d1-f66832cfd499', 'Check whether the unified player is installed', 'Request the installed package list through the framework package-list operation and inspect the returned package details for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.360994', '2026-10-07 05:11:12.360995');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d81f1952-98f4-4aac-a81a-746802ba0ad8', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using Controller.1.status@<plugin> requests. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.361826', '2026-10-07 05:11:12.361827');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1fe55df2-3d8b-47e4-b347-e625dea19879', 'Download the unified player bundle', 'Download the configured application bundle from <configured application download URL>/<bundle name>.', 'The application bundle should download successfully and return package details for installation.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.362033', '2026-10-07 05:11:12.362033');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f875b428-984d-49f4-a1bb-7925a72ea128', 'Install the unified player bundle', 'Install the downloaded package using the configured file locator and the derived application ID.', 'The bundle should install successfully.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.362229', '2026-10-07 05:11:12.362230');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1c52b465-006b-41d1-a6a1-2f516b381cdb', 'Verify the installed application', 'Query the installed package list again and check that the derived application ID is present.', 'The application ID should appear in the installed package list.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.363191', '2026-10-07 05:11:12.363192');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ddf974c9-c443-4c8c-99e0-eb5066a5c8c9', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should succeed.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.363432', '2026-10-07 05:11:12.363433');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bd14c47c-0425-4b2e-81e7-100cf5cd96cc', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.364419', '2026-10-07 05:11:12.364420');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2dd99291-6f16-442f-95fc-5f34ea3f5e11', 'Wait for the video playback event', 'Monitor the application log until an entry containing Video Player Playing is received, and extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.365291', '2026-10-07 05:11:12.365292');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('007911c6-56cb-4d64-bd38-cea142b7021b', 'Read the WPE load timestamp', 'On the device, obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest WPE load timestamp with grep -i ''wpe load committed'' <app log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.366141', '2026-10-07 05:11:12.366142');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('869ad405-4d61-4353-9802-e2f9d4599427', 'Calculate time to video playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.366975', '2026-10-07 05:11:12.366976');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('77bd2304-ec8d-466e-b56c-1df2aacf2ee2', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to video playback should be within the configured threshold; otherwise the test should fail.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.367774', '2026-10-07 05:11:12.367774');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('506f4fd7-9f76-4540-9268-f80dd59dbec3', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.367992', '2026-10-07 05:11:12.367993');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('083ff2d8-35e0-4c5e-a7de-d6929d0ad77d', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states using the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.368826', '2026-10-07 05:11:12.368827');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ad03b61f-9f5e-450a-9e55-b2597671a899', 'Record the execution summary and unload the module', 'Record the threshold values, timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '5f01dfbd-19d2-4f39-be74-4146238d28b1', '2026-10-07 05:11:12.369029', '2026-10-07 05:11:12.369030');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e14145a9-6794-4645-b3c9-ed611779f797', 'Set playback operations for each stream.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for all streams.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.056581', '2026-09-08 07:19:13.056584');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('00f1010e-575c-49b7-8ed1-d8ec92fbcdea', 'Store all three stream URLs as a list in PersistentStore.', 'Construct and store all three stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d0c21f59-958a-443c-a558-aa8852adff3f', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2dda1531-8b14-4e0f-b843-48d0df94aa16', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3ed96231-5dff-4404-a331-620b12dfce4d', 'Load the first stream (DASH H264) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH H264 playback.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.062635', '2026-09-08 07:19:13.062637');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c8732306-4a09-4d22-a3a8-f505a03ae407', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 playback.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.063484', '2026-09-08 07:19:13.063485');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c7abeddf-db6b-449d-9cd9-9b1825b2519e', 'Clear the browser, load the second stream (DASH AV1) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH AV1 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH AV1 stream loads and media events are captured.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.064332', '2026-09-08 07:19:13.064333');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d12b7ca1-9826-434f-8326-a388bf9f561d', 'Validate observed events for the second playback and record intermediate result.', 'If the DASH AV1 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH AV1 playback.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.065228', '2026-09-08 07:19:13.065230');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e768f485-8ce5-4568-8a8f-af73ba302233', 'Clear the browser, load the third stream (DASH HEVC) and capture media events.', 'The browser is cleared after the second playback. The player then loads the third URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH HEVC stream loads and media events are captured.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.065492', '2026-09-08 07:19:13.065493');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('42d77723-3710-4ddd-96a2-0eec373d1cce', 'Validate observed events for the third playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the third stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.065727', '2026-09-08 07:19:13.065729');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('778551ca-509a-42cc-8045-8514d75b651d', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if all the DASH H264, DASH AV1 and DASH HEVC playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of all three playbacks.', '1e8757e1-f96e-47a2-aa9b-b016f0a9cf7c', '2026-09-08 07:19:13.066646', '2026-09-08 07:19:13.066648');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7646841f-1e5c-48e5-a347-a11939a85ec3', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('67317470-d076-41dd-bc90-cc5974290780', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'fa4cfee4-6ad4-4993-a9e7-982821c19c2b', '2026-10-05 08:36:45.785236', '2026-10-05 08:36:45.785239');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('db90834b-6fde-428b-8d20-0a4174970f95', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6fc8298b-38fd-4532-abb1-a92061ecf753', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6215ff6c-5110-4864-92a4-9d44b424571c', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('010cbcac-2277-408a-b247-427a5e8c2f21', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'fa4cfee4-6ad4-4993-a9e7-982821c19c2b', '2026-10-05 08:36:45.789434', '2026-10-05 08:36:45.789436');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('904b15fb-382a-4c71-ac2c-c6787000b5bd', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'fa4cfee4-6ad4-4993-a9e7-982821c19c2b', '2026-10-05 08:36:45.790389', '2026-10-05 08:36:45.790391');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cf4d19b1-3f5e-43c7-b3b5-3fcc7efb8aca', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('304e4018-2c75-440e-960e-e265561895e6', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Cancel_LargeFile_Download.', 'The performance test module should load successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.673573', '2026-09-08 06:26:14.673577');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('23990bea-2917-4062-8937-fc4230315fcc', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.674079', '2026-09-08 06:26:14.674084');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1f5abb78-a61e-47f3-9ce0-0e04fb348a80', 'Retrieve the package storage locator', 'Read PACKAGEMANAGER_FILE_LOCATOR from the device configuration and derive the package directory by retaining the path before /CDL and appending /CDL/.', 'The package storage directory should be resolved successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.675270', '2026-09-08 06:26:14.675275');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e853ff34-4d28-42c5-9d3a-19d315722ce4', 'Retrieve SSH connection details', 'Read the configured SSH method, device IP, username, and password from the device configuration for remote command execution.', 'Valid SSH method and credentials should be available.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.675814', '2026-09-08 06:26:14.675819');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1208a4e7-bf28-495e-871d-0ea4a2f08338', 'Measure initial package storage usage', 'Execute the following remote command against the package storage directory: du -sk <file_locator>/CDL/ | awk ''{print $1}''.', 'The initial package storage usage should be returned as a numeric value in KB.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.676908', '2026-09-08 06:26:14.676913');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('01420b26-af41-4aa9-ab5f-ec9943630531', 'Subscribe to application download status events', 'Register for download status notifications at /jsonrpc using the following payload: {"jsonrpc": "2.0","id": 2,"method": "org.rdk.DownloadManager.1.register","params": {"event": "onAppDownloadStatus", "id": "client.events.1" }}.', 'The event subscription should be established successfully.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.678074', '2026-09-08 06:26:14.678078');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('01d63137-6153-423b-9748-295c60c21a01', 'Start downloading the large application bundle', 'Request the bundle download using org.rdk.DownloadManager.1.download with the configured URL and the Large_Validation_File name: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url><Large_Validation_File>"}}.', 'The download request should return success and a download ID.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.679498', '2026-09-08 06:26:14.679503');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('50c8e93d-4a3f-41b8-8367-0345068735c9', 'Query the download progress', 'Query the download progress for the returned download ID using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}.', 'The progress request should return a numeric percentage greater than 0 and less than 100.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.680888', '2026-09-08 06:26:14.680892');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dd3cefa1-d11a-4953-94b8-e5a07798ed43', 'Cancel the active download', 'Cancel the in-progress download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.cancel","params":{"downloadId":"<download_id>"}}.', 'The cancellation request should return success.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.682027', '2026-09-08 06:26:14.682031');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6aa9185-1b86-4b7e-abde-8369f433263b', 'Poll for the cancellation status event', 'Poll the subscribed event buffer for up to 120 seconds and retrieve the first available event.', 'An onAppDownloadStatus event should be received and should indicate DOWNLOAD_FAILURE for the cancelled download.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.683450', '2026-09-08 06:26:14.683454');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6c74a726-92ec-4e3b-aa16-731aea60a4a2', 'Validate the cancellation event details', 'Parse the event and compare its downloadId with the requested download ID. Confirm that its fileLocator contains the same download ID. The event data must contain fields equivalent to {"downloadId":"<download_id>","fileLocator":"<file_locator>"} within the download status entry.', 'The event download ID should match the requested ID, and the file locator should identify the cancelled package.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.683979', '2026-09-08 06:26:14.683983');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('989afcc6-22b4-415a-b3eb-7a89a8b3e2d8', 'Delete the cancelled package', 'Delete the package identified by the event file locator using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.delete","params":{"fileLocator":"<file_locator>"}}.', 'The package deletion request should return success.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.685180', '2026-09-08 06:26:14.685185');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('741c3635-bf3c-4753-a6b2-b49a465c93c0', 'Verify package deletion from storage', 'Execute the following remote command for the event file locator: ls -l <file_locator>.', 'The command output should contain No such file or directory, confirming that the cancelled package was removed.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.687304', '2026-09-08 06:26:14.687309');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e5217986-8278-486b-a94a-629cd2195e14', 'Measure package storage after deletion', 'Execute du -sk <file_locator_directory> | awk ''{print $1}'' against the package storage directory and compare the result with the initial usage.', 'The final package storage usage should be less than or equal to the initial usage.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.688551', '2026-09-08 06:26:14.688555');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4fcecb62-e13c-4f85-9530-00150acb0593', 'Close the download event subscription', 'Disconnect from the download status event stream after all validations are complete.', 'The event subscription should close cleanly and the testcase should finish without an active listener.', 'b43461c4-a119-4748-835e-86fdee46a598', '2026-09-08 06:26:14.689642', '2026-09-08 06:26:14.689647');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d4c78e6f-4f31-4616-8024-74c78dcc9eaf', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.102472', '2026-10-08 04:56:31.102473');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c0891a65-ed55-4e87-b18e-4f6604875eac', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.103441', '2026-10-08 04:56:31.103442');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d5ecd090-5391-4962-80b1-09252bf4ccc4', 'Build the AV1 player test URL', 'Combine the configured AV1 source URL, AV1 URL type, selected codec_av1 player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete AV1 player test URL should be generated.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.105046', '2026-10-08 04:56:31.105047');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('672788ad-ead2-4e1f-bcea-4c594a2c021f', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated AV1 player test URL>"}}.', 'The AV1 player URL should be stored successfully in PersistentStore.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.105263', '2026-10-08 04:56:31.105264');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('017cff32-a686-4f9e-a275-95f494e6e4be', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.105480', '2026-10-08 04:56:31.105481');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bac6f240-7424-4f0a-944f-6e45de0d877e', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.107036', '2026-10-08 04:56:31.107037');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('64e0cbea-5072-4b4d-a049-71432edb1623', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.107901', '2026-10-08 04:56:31.107902');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3cdbe74f-7b29-4f61-95d8-eeaee9a4411b', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.108707', '2026-10-08 04:56:31.108708');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('39543bd0-4ee5-4eac-b839-ac6caf7910c3', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.109539', '2026-10-08 04:56:31.109540');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('445ba169-110c-4798-bdc0-520f0f358857', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.109772', '2026-10-08 04:56:31.109772');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('54606e6d-3dd1-46ff-93fb-0e8b0d126fcc', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.110648', '2026-10-08 04:56:31.110649');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('41b3963d-0c02-4533-a8bd-5416cdcb7620', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.111547', '2026-10-08 04:56:31.111548');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e4c6d344-04ce-42da-8fe0-5adfc200212d', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.112341', '2026-10-08 04:56:31.112342');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6c22eb83-2399-45c8-b138-2e8c09d10a60', 'Calculate time to AV1 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.112527', '2026-10-08 04:56:31.112528');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0df40101-6347-424d-bc40-7b0b46196f77', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to AV1 playback should be within the configured threshold; otherwise the test should fail.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.113384', '2026-10-08 04:56:31.113385');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6918192-bb53-4bd8-92c9-5871c6f1cb93', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.114152', '2026-10-08 04:56:31.114153');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2a88f251-d17f-4579-a066-48dec97f1c8a', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.115004', '2026-10-08 04:56:31.115005');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7b3bd8eb-0f15-4088-9667-22a057e458c4', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '1e6eeaf3-77ee-4118-8925-95ba8bed3b76', '2026-10-08 04:56:31.115185', '2026-10-08 04:56:31.115186');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('018b3788-786c-4d9d-a8cb-fa13886e47f8', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '04307d92-717d-4d12-b5c5-76e1dcfcaaf5', '2026-10-06 10:52:29.842991', '2026-10-06 10:52:29.842992');
