INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('29fb446a-1909-4840-a4eb-1b098ecebd7e', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.661853', '2026-10-07 04:54:18.661854');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4c8703af-6441-477d-ad75-155683bd7287', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.662180', '2026-10-07 04:54:18.662181');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('368e2c69-b41c-4202-ae8e-1010518372c1', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.663199', '2026-10-07 04:54:18.663200');
