INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d10e9978-af54-41af-a6ef-f6215c159552', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.664532', '2026-10-07 04:54:18.664533');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5fd49c7f-5fc6-4a51-9ce9-80ac5e43bb77', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.665548', '2026-10-07 04:54:18.665549');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8eeb15b0-1b72-44b1-89ec-aaf8c9261c70', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.666610', '2026-10-07 04:54:18.666612');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('45e660ac-b7f6-41d0-a97a-fa64f6030e03', 'Calculate time to HLS H.264 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.666968', '2026-10-07 04:54:18.666969');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('965e42c6-453d-4550-846c-ff7cd31fd80c', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to HLS H.264 playback should be within the configured threshold; otherwise the test should fail.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.667363', '2026-10-07 04:54:18.667364');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('01aa4d55-14e7-4853-9362-1fb3e78b186b', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.668399', '2026-10-07 04:54:18.668400');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('16424610-eaa4-4686-9dc0-9bb20a1ae498', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.668738', '2026-10-07 04:54:18.668740');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('244d0a73-6ae2-4b78-8149-40047b92bf75', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '41dca5ba-cf27-4ab0-ab5c-ce9d653b2be2', '2026-10-07 04:54:18.669054', '2026-10-07 04:54:18.669056');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3bfa02b0-5342-4d9b-aefa-1a3e50573438', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.959851', '2026-10-06 17:58:44.959853');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c8ae6bd8-906a-4d9b-a19c-d7c6d1a4b70d', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.961434', '2026-10-06 17:58:44.961435');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1e6e0617-40b8-47bc-94ad-9dc142f78f72', 'Build the DASH H.264 player test URL', 'Combine the configured DASH H.264 source URL, dash URL type, selected codec_dash_h264 player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete DASH H.264 player test URL should be generated.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.962337', '2026-10-06 17:58:44.962338');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7d86930f-b118-4055-9252-cd97feb56db9', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated DASH H.264 player test URL>"}}.', 'The DASH H.264 player URL should be stored successfully in PersistentStore.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.964145', '2026-10-06 17:58:44.964146');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2bc3e490-1d3c-4557-9ea2-a19fa08b266b', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.965063', '2026-10-06 17:58:44.965064');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('54052344-08d8-4936-8835-c9e692d27223', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.965854', '2026-10-06 17:58:44.965855');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a809d59f-3a12-4731-851d-973f7e44fd15', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.966075', '2026-10-06 17:58:44.966075');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('27cdd4dd-1973-4a82-b6b3-54adccc3b695', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.966909', '2026-10-06 17:58:44.966910');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d76d2412-f39a-44d0-abe5-8269209ccba0', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.968386', '2026-10-06 17:58:44.968387');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a7046584-b707-48ef-89ff-2c43f8de2af4', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.969859', '2026-10-06 17:58:44.969860');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('43d96423-c5ab-4a5b-bddf-2d9f51fb1e17', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.970787', '2026-10-06 17:58:44.970788');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d17b4166-9bd8-435b-af76-573f84552f04', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.971086', '2026-10-06 17:58:44.971087');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2f53c562-2c49-4d6b-b99b-0f1d3e3a5b33', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.971936', '2026-10-06 17:58:44.971937');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b7938e53-b007-4003-89fb-504d97866635', 'Calculate time to DASH H.264 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.972149', '2026-10-06 17:58:44.972150');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a082a416-ce1d-4834-a85b-9c1633e42835', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to DASH H.264 playback should be within the configured threshold; otherwise the test should fail.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.972383', '2026-10-06 17:58:44.972384');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('576096e2-6783-48c6-ad5a-e0c16070ff75', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.973250', '2026-10-06 17:58:44.973251');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f91d185-a853-48c2-bd6f-9678f871d954', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.974799', '2026-10-06 17:58:44.974800');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('01d12ea5-785e-44bc-918d-b2f70b45024f', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '8b43d51f-996c-48a0-a27d-54c84d992323', '2026-10-06 17:58:44.975641', '2026-10-06 17:58:44.975642');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('df61576f-51eb-48fd-9ecc-b5f01badb4ec', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager.', 'The required application services should be activated successfully.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.572307', '2026-10-07 07:44:21.572309');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7b1eaa67-ff7c-43c3-a8d5-ec0ffa37bfb2', 'Install the application under test', 'Download and install the configured Google application bundle for application com.rdkcentral.google, and verify that installation succeeds.', 'The application should be installed successfully before lifecycle validation begins.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.575871', '2026-10-07 07:44:21.575872');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('72c5b50a-ab13-4ef8-8e46-96f3ea5d4872', 'Launch the application', 'Submit an application launch request using com.rdkcentral.google as the application name.', 'The launch request should return success.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.576751', '2026-10-07 07:44:21.576752');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e4174fe4-7191-48d6-81e6-171fe0606c95', 'Verify application loading', 'After the launch request, read the loaded-application list and verify that com.rdkcentral.google is present.', 'The application should appear in the loaded-application list.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.577614', '2026-10-07 07:44:21.577615');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('029e3981-a73b-492f-a439-2a3f7c151269', 'Clear application data', 'Clear data for the running application using the AppManager JSON-RPC method: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.clearAppData","params":{"appId":"com.rdkcentral.google"}}.', 'The clear-data request should return success and the application data should be cleared.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.578441', '2026-10-07 07:44:21.578442');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('663644ca-0ef9-4651-be55-2b5dd4e40bb8', 'Terminate the application', 'Terminate com.rdkcentral.google using its application identifier.', 'The application termination request should return success.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.579261', '2026-10-07 07:44:21.579262');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2b173630-e8bc-4d18-83f0-395eaeb7c23b', 'Verify application termination', 'After termination, read the loaded-application list and verify that com.rdkcentral.google is no longer present.', 'The application should not appear in the loaded-application list after termination.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.580184', '2026-10-07 07:44:21.580185');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9fb7f891-27f0-49b3-9e82-0d141a0eb0f0', 'Validate resource usage', 'Request resource-usage validation after the application is terminated.', 'The application should not appear in the loaded-application list after termination.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.580992', '2026-10-07 07:44:21.580993');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6c55ef92-5fbe-459c-b210-800839bf8b63', 'Repeat the application lifecycle validation', 'Repeat the launch, loaded-state verification, app-data clearing, termination, termination verification, and resource-usage validation actions for the configured application manager test count.', 'The complete lifecycle block should execute for every configured iteration, and any failed lifecycle or resource check should mark the corresponding iteration unsuccessful.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.581862', '2026-10-07 07:44:21.581863');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('336c7603-8e2e-44c4-95b0-9329b7d111fa', 'Complete the test module', 'Unload the rdkv_stability test module after the lifecycle iterations complete.', 'The test module should be unloaded cleanly and the final test status should reflect the observed results.', '390e11e9-50fe-442b-8f54-1ac53f9ec7c1', '2026-10-07 07:44:21.582655', '2026-10-07 07:44:21.582656');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('12988b37-00ac-47e4-a93b-e49f67db0038', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', 'bb401c21-da25-43fd-80a0-bc62f9c136ef', '2026-09-08 07:15:00.723513', '2026-09-08 07:15:00.723515');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('02b280a7-b2bf-4943-83e6-cb4738e7e6c7', 'Test Step 2', 'The application starts playing a Widevine DRM-protected AC3 DASH stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The DASH AC3 stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', 'bb401c21-da25-43fd-80a0-bc62f9c136ef', '2026-09-08 07:15:00.724497', '2026-09-08 07:15:00.724499');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9e71a7dd-8c4f-4bb1-8045-016e0b387185', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', 'bb401c21-da25-43fd-80a0-bc62f9c136ef', '2026-09-08 07:15:00.725470', '2026-09-08 07:15:00.725472');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4376aa7f-366a-4704-a996-dbc8f43882c7', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', 'bb401c21-da25-43fd-80a0-bc62f9c136ef', '2026-09-08 07:15:00.726401', '2026-09-08 07:15:00.726402');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('180d3b49-f3c5-4222-9639-0e4e57101a41', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', 'bb401c21-da25-43fd-80a0-bc62f9c136ef', '2026-09-08 07:15:00.727407', '2026-09-08 07:15:00.727409');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e45fab61-97a7-455b-aae6-6e5faf058a25', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '75c2f4d2-0de1-47d2-a273-5c7c4c337197', '2026-10-07 06:56:10.893953', '2026-10-07 06:56:10.893955');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('65f70f2c-2099-479e-b3ba-0469cd7389f3', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e22a1725-eebc-4a74-ae97-0af1fb29c2c5', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('23a7c465-864c-4f67-9aed-2d403ef2e332', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('02b3427b-8873-47a5-bdfa-629737ad257a', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '75c2f4d2-0de1-47d2-a273-5c7c4c337197', '2026-10-07 06:56:10.903333', '2026-10-07 06:56:10.903334');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3f08a1c5-d14f-427e-b80e-7decccde21cf', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '75c2f4d2-0de1-47d2-a273-5c7c4c337197', '2026-10-07 06:56:10.905337', '2026-10-07 06:56:10.905338');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2ac901cb-458c-45ce-9cd9-754c92c1ea7a', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b2742b86-37fa-42d5-88c5-f723fd2579dc', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.127449', '2026-09-08 07:18:49.127451');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('02fb67cc-572b-4ea1-9e83-55f2439d68db', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f6385c68-00b1-4db0-872c-c7d8fb7b5027', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d74a44bc-aa65-4e43-8ed3-30cbb4e0065a', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6e936b1e-2290-403a-82ba-07ecbc72796d', 'Load the first stream (DASH H264 AC3) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH H264 AC3 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH H264 AC3 playback.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.129097', '2026-09-08 07:18:49.129099');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f9bb2732-b724-44a2-88b1-a31a777c9bd6', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH H264 AC3 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 AC3 playback.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.130041', '2026-09-08 07:18:49.130043');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('680581c8-8bb1-4d7d-a085-d7cdb624654b', 'Clear the browser, load the second stream (DASH H264 EC3) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH H264 EC3 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH H264 EC3 stream loads and media events are captured.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.131001', '2026-09-08 07:18:49.131003');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('19f8e33c-7b8a-40bf-8737-e716f25cd45d', 'Validate observed events for the second playback and record intermediate result.', 'If the DASH H264 EC3 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 EC3 playback.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.131902', '2026-09-08 07:18:49.131904');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4d1fda89-1edc-480b-823b-1bb424f8c55e', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH H264 AC3 and DASH H264 EC3 playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'e1727c67-15e8-4e14-8e51-819d338d6cf3', '2026-09-08 07:18:49.132774', '2026-09-08 07:18:49.132776');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3dae5f21-4897-4205-be6f-8b3fad6ae4a9', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('45c53c98-3ac6-4dfe-a1c8-76d7bd175213', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.163702', '2026-10-08 04:49:05.163703');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5fce671c-f5b4-4687-a472-cb94be483beb', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.163928', '2026-10-08 04:49:05.163929');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e5e850ed-2598-4678-9b35-ceefb538eada', 'Select the 4K DASH HEVC codec player', 'Split codec_dash_hevc into the configured player identifiers and use video_src_url_4k_dash with URL type dash.', 'The selected player list should correspond to the 4K DASH HEVC source.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.164794', '2026-10-08 04:49:05.164794');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('896236a2-9c60-4894-93d8-c358ad5d7137', 'Build the 4K DASH player test URL', 'Combine the 4K DASH source URL, URL type dash, selected codec player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete 4K DASH HEVC player test URL should be generated.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.165822', '2026-10-08 04:49:05.165823');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dcb20f36-ff1f-465b-b38f-9169d47d2ca2', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated 4K DASH HEVC player test URL>"}}.', 'The 4K DASH HEVC player URL should be stored successfully in PersistentStore.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.166123', '2026-10-08 04:49:05.166124');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d5d6c193-aa5f-4a65-a592-03ec66106e66', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.167158', '2026-10-08 04:49:05.167160');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2c95f45a-a67c-4171-b3ac-0821f056b16b', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.168153', '2026-10-08 04:49:05.168154');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('27e1a334-489e-4ad8-879d-2ade34fe268e', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.168564', '2026-10-08 04:49:05.168566');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('56abaad5-b1a1-480e-bee7-7db9ee69cc79', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.170467', '2026-10-08 04:49:05.170468');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3721e148-98e9-4e28-88ef-0f125aa2d044', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.171532', '2026-10-08 04:49:05.171534');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6b22833-444d-4748-a275-38cb232abf0d', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.172534', '2026-10-08 04:49:05.172535');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2c1a5a5e-7aed-4550-826c-a580a62c0184', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.172854', '2026-10-08 04:49:05.172855');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ed3a339f-7acb-4f1e-8c12-bf1c1e60d386', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.173787', '2026-10-08 04:49:05.173788');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e6430b56-b9ec-4f83-b03b-8326c70a5695', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.174715', '2026-10-08 04:49:05.174716');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('038b4be5-b400-48f7-881f-df3e7a2934b1', 'Calculate time to 4K DASH playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.175109', '2026-10-08 04:49:05.175111');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('99e30f48-f6ef-4863-add6-a7b9f6b1ea20', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to 4K DASH playback should be within the configured threshold; otherwise the test should fail.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.175420', '2026-10-08 04:49:05.175421');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b5376b9f-b6b7-4e13-ae08-2ccf18418c15', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.176465', '2026-10-08 04:49:05.176466');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('57439827-53fb-4db8-917d-56b6b1889750', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.178242', '2026-10-08 04:49:05.178243');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('409d3c08-2748-41ae-bcc7-9e25f3008333', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '141962e4-a781-4b15-977b-7c542e4eadcf', '2026-10-08 04:49:05.178555', '2026-10-08 04:49:05.178557');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('702478f7-1ec8-4ded-96c9-92921a250831', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.735592', '2026-10-08 04:46:04.735593');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('66c1303e-c831-4754-8532-579de7516b9b', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.736516', '2026-10-08 04:46:04.736517');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('417645da-aaba-4bdc-be26-51c0a8d93335', 'Build the 4K AV1 player test URL', 'Combine the configured 2160p AV1 source URL, AV1 URL type, selected codec/player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete 4K AV1 player test URL should be generated.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.737398', '2026-10-08 04:46:04.737399');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8086aa0f-08c1-46bf-a2a2-ef4b57909257', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated 4K AV1 player test URL>"}}.', 'The 4K AV1 player URL should be stored successfully in PersistentStore.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.740338', '2026-10-08 04:46:04.740339');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e88de455-a5c5-45f9-874d-100e0625abfa', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.741583', '2026-10-08 04:46:04.741584');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('045bfe3f-d897-45d4-8c0a-a8cb695d3f39', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.743356', '2026-10-08 04:46:04.743357');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('eb76f1f5-7c88-4e26-9d5a-e461d694b871', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.744370', '2026-10-08 04:46:04.744371');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bf15295b-e4bd-4be5-839c-eb349db1be64', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.746008', '2026-10-08 04:46:04.746010');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('548caf7c-949f-46cd-b803-acf7c4ad3adb', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.746234', '2026-10-08 04:46:04.746235');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3945ff6d-9711-4ee8-ba84-14674720efd7', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.746464', '2026-10-08 04:46:04.746465');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('90a9f5ae-7256-4713-b06d-b21fe53c6eb7', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.747953', '2026-10-08 04:46:04.747954');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('573ffa2a-8fc7-4f45-9869-40df3771ef5d', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.748802', '2026-10-08 04:46:04.748803');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('59ae530b-e141-4ec6-8ba7-e3821ea09e03', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.749641', '2026-10-08 04:46:04.749642');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6c8b44c3-2b24-4eb3-9200-9c2545f5d0cc', 'Calculate time to video playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.749840', '2026-10-08 04:46:04.749841');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a354896b-4237-4501-923f-2c1690b1b2cf', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to 4K AV1 video playback should be within the configured threshold; otherwise the test should fail.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.750020', '2026-10-08 04:46:04.750021');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5e803500-78d1-498f-aa58-a271e1f027ec', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.750901', '2026-10-08 04:46:04.750902');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0424a554-b41e-4ee3-bce6-8ad9023f9385', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.751776', '2026-10-08 04:46:04.751777');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0989d415-e92d-4678-8836-b0b0e3e3f2e1', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '0f160569-cd73-4123-897d-3b2e36fec8fb', '2026-10-08 04:46:04.752592', '2026-10-08 04:46:04.752593');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c5b9a089-244a-4cee-bf24-320c3b871b0c', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Download_InvalidURL.', 'The performance test module should load successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.210112', '2026-09-08 06:25:43.210118');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('31ac3068-5359-42f0-a019-e3b79fc8d89a', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.214987', '2026-09-08 06:25:43.215000');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c74db8f9-dd21-4247-89cb-f52b33ae7380', 'Retrieve SSH connection details', 'Read the configured SSH method and credentials for the device and make them available for remote verification commands.', 'Valid SSH method and credentials should be retrieved successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.216193', '2026-09-08 06:25:43.216198');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('46e8db80-5019-4a3d-b85a-7d0285f77b2f', 'Subscribe to application download status events', 'Register for download status notifications at /jsonrpc using {"jsonrpc": "2.0","id": 2,"method": "org.rdk.DownloadManager.1.register","params": {"event": "onAppDownloadStatus", "id": "client.events.1" }}.', 'The event subscription should be established successfully.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.217647', '2026-09-08 06:25:43.217652');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1c9f7da8-568b-427b-b15f-de56237ba9b7', 'Prepare the valid and invalid download URLs', 'Build the valid URL from app_download_url and google_bundle, and build the failing URL from invalid_download_url and the same bundle name.', 'Both test URLs should be constructed successfully, with only the valid URL pointing to the application bundle location.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.218941', '2026-09-08 06:25:43.218946');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ecbb4fa7-bccf-4de7-88c9-f606ff56df40', 'Clear previously received events', 'Clear the download event buffer before starting the invalid-URL test.', 'Previously buffered events should be removed.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.220702', '2026-09-08 06:25:43.220706');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6b30e3a-3837-4190-b262-e854938cface', 'Request a download from the invalid URL', 'Submit the invalid URL to org.rdk.DownloadManager.1.download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<invalid_download_url>/<google_bundle>"}}.', 'The download request should fail rather than return success.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.222017', '2026-09-08 06:25:43.222022');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('90eae54e-3ef1-4a01-b937-5b4dcd4f6c81', 'Process the invalid-URL download result', 'Execute the invalid-URL download test operation a second time as implemented by the script, then read the returned status and details.', 'The resulting status should remain unsuccessful for the invalid URL.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.223686', '2026-09-08 06:25:43.223691');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('462a6054-8910-4de6-96c9-d63566f82b26', 'Process the invalid-URL download result', 'Execute the invalid-URL download test operation a second time as implemented by the script, then read the returned status and details.', 'The resulting status should remain unsuccessful for the invalid URL.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.224936', '2026-09-08 06:25:43.224941');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a614c8bf-f950-4d58-b45b-b794c086e32d', 'Validate the invalid-URL failure event', 'Poll the subscribed event buffer for up to 120 seconds and retrieve the first available event.', 'An onAppDownloadStatus event should be received and should contain DOWNLOAD_FAILURE.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.226569', '2026-09-08 06:25:43.226576');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('419f855c-3dae-4cb6-9290-5c76fa56e5fa', 'Clear events before the valid download', 'Clear the event buffer after validating the invalid-URL failure and before starting the valid download.', 'The event buffer should contain no stale invalid-URL event.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.227765', '2026-09-08 06:25:43.227770');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('04aa99b2-7262-40e7-a8f4-9babd14140e3', 'Request a download from the valid URL', 'Submit the valid URL to org.rdk.DownloadManager.1.download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The download request should return success and a download ID.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.228991', '2026-09-08 06:25:43.228995');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('248d200d-73a4-4fbd-b4de-99281df23a4f', 'Validate the successful download event', 'Poll the event buffer for up to 120 seconds. Confirm that the received onAppDownloadStatus event does not contain DOWNLOAD_FAILURE, then parse its download status entry and obtain downloadId and fileLocator.', 'A non-failure download status event should be received, and it should contain a valid download ID and file locator.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.230264', '2026-09-08 06:25:43.230268');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('af473844-f6e7-4c21-9a4e-d0940eb9f8c5', 'Match the event to the download request', 'Compare the event downloadId with the returned download ID and confirm that the event file locator contains that download ID.', 'The event download ID should match the request ID, and the file locator should identify the requested package.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.231577', '2026-09-08 06:25:43.231582');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ec5177c-fb92-4e39-a785-7514c0e35ae5', 'Delete the downloaded package', 'Delete the package using org.rdk.DownloadManager.delete with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.delete","params":{"fileLocator":"<file_locator>"}}.', 'The package deletion request should return success.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.232785', '2026-09-08 06:25:43.232790');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('08af64a0-0f6f-44a5-bb26-0e85a83a147e', 'Verify package deletion from storage', 'Execute the remote command ls -l <file_locator> using the configured SSH connection.', 'The command output should contain No such file or directory or cannot access, confirming that the package no longer exists on the device.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.234036', '2026-09-08 06:25:43.234040');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5f6eda4b-9291-4b87-b185-5a53f6680b66', 'Close the download event subscription', 'Disconnect from the download status event stream after all validations are complete.', 'The event subscription should close cleanly and the testcase should finish without an active listener.', 'e37965a7-2826-4ca8-ac3e-b02699291687', '2026-09-08 06:25:43.235312', '2026-09-08 06:25:43.235317');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('33610e90-919a-41d5-9340-74eb5f14d02d', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.504396', '2026-10-06 19:15:45.504398');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ae2cc828-b284-483c-a7b6-0faed9e76d03', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.505500', '2026-10-06 19:15:45.505501');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('84c15758-3df9-4320-af8b-57771427e39c', 'Build the EC3 player test URL', 'Combine the configured EC3 source URL, EC3 URL type, selected codec_ec3 player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete EC3 player test URL should be generated.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.506501', '2026-10-06 19:15:45.506502');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fcfced84-d10e-482a-835e-0ddf1b671cb4', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated EC3 player test URL>"}}.', 'The EC3 player URL should be stored successfully in PersistentStore.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.507625', '2026-10-06 19:15:45.507626');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6a3a2bee-0f06-4082-98d7-35e6b4c36b84', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.507959', '2026-10-06 19:15:45.507961');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2182f6d4-7bc3-4a61-ae94-68ce21bc01fa', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.509047', '2026-10-06 19:15:45.509049');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fff12fe1-6aca-4624-b563-2a51f9674009', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.Install the unified player bundle', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.510762', '2026-10-06 19:15:45.510763');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dbece702-070b-4493-96a8-d9bcd5a21ca3', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.511118', '2026-10-06 19:15:45.511119');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d8b5d1fd-e2d4-4587-9407-ea0544f2c423', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.512107', '2026-10-06 19:15:45.512108');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('78011d18-2b20-4f28-8624-4fe35783743a', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.512446', '2026-10-06 19:15:45.512447');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7c8eeace-4bb4-4c27-84db-4ee0b9d6bed9', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.513459', '2026-10-06 19:15:45.513460');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0fe09db2-093a-4902-a6c3-b0d74abb33ef', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.515264', '2026-10-06 19:15:45.515265');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('70b78773-396a-44bc-bc4a-11f69cd83b5a', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.516346', '2026-10-06 19:15:45.516347');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f7019c79-1f9f-42fa-be75-de151463d58d', 'Calculate time to EC3 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.517433', '2026-10-06 19:15:45.517435');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1b14b073-6fb7-4d30-96f7-0cff8ed1560b', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to EC3 playback should be within the configured threshold; otherwise the test should fail.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.518441', '2026-10-06 19:15:45.518442');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4b2ef133-8c4f-43f5-b1bc-a369738dc852', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.518690', '2026-10-06 19:15:45.518690');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('922a8390-e1f8-4935-805c-15d1e6217cee', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.519553', '2026-10-06 19:15:45.519554');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('04c811e9-b2d3-42f8-ba67-ff5a78b109de', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'b9ba4d51-4f2d-489a-8f96-bf903a264cce', '2026-10-06 19:15:45.520457', '2026-10-06 19:15:45.520458');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9daf80ed-e4a1-4efe-888c-8928e00abc5d', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager.', 'The required application services should be activated successfully.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.044523', '2026-10-07 08:24:16.044524');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('629ebd3a-87e6-4d7a-92d4-a48246229eea', 'Subscribe to uninstall events', 'Register a listener for application uninstall events using: {"jsonrpc": "2.0","id": 1,"method": "org.rdk.AppManager.1.register","params": {"event": "onAppUninstalled", "id": "client.events.1" }}.', 'The uninstall event subscription should be registered successfully.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.045450', '2026-10-07 08:24:16.045451');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f08a65e8-dfd5-481e-b767-7455e4e9f1fe', 'Install or verify the application', 'Download and install the configured Google application bundle for com.rdkcentral.google, or verify that the application is already installed.', 'The application should be installed and available for launch.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.046402', '2026-10-07 08:24:16.046403');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('04d49452-0440-4ee4-b223-393b42f62086', 'Launch the application', 'Submit a launch request for com.rdkcentral.google.', 'The launch request should return success.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.047380', '2026-10-07 08:24:16.047380');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e107931d-9a64-4c5e-8cd9-d8bdb64a7b72', 'Verify the application is active', 'Query loaded applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps","params":{}}. Confirm that com.rdkcentral.google is present and has the APP_STATE_ACTIVE lifecycle state.', 'The application should be present in the loaded-application list with an active lifecycle state.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.047574', '2026-10-07 08:24:16.047575');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd7e89c3-10c3-4187-830b-a53f2ea88312', 'Attempt to uninstall the active application', 'Submit an uninstall request for com.rdkcentral.google while it remains active.', 'The uninstall request should fail, and the active application record should remain valid.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.049091', '2026-10-07 08:24:16.049092');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('70968100-5089-4852-adc5-dcce4c64657a', 'Verify the active application remains loaded', 'After the rejected uninstall request, read the loaded-application list and verify that com.rdkcentral.google is still present.', 'The application should remain present in the loaded-application list after the rejected uninstall attempt.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.049910', '2026-10-07 08:24:16.049911');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5226acc0-8c41-48d2-90cc-1d67811f9d70', 'Terminate the active application', 'Terminate com.rdkcentral.google using its application identifier.', 'The termination request should return success.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.050712', '2026-10-07 08:24:16.050713');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5d4cb102-f063-495e-8e76-ae170f88310e', 'Verify automatic removal after termination', 'Query installed applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getInstalledApps","params":{}}.', 'com.rdkcentral.google should no longer appear in the installed-application list after termination.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.051501', '2026-10-07 08:24:16.051502');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('352f399c-9c05-41fd-a4f6-86002d34bacd', 'Repeat the uninstall-conflict validation', 'Repeat application installation or verification, launch, active-state validation, active uninstall attempt, loaded-state validation, termination, and installed-application validation for the configured application manager test count.', 'Each configured iteration should reject uninstall while the application is active and should remove the application after successful termination.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.053116', '2026-10-07 08:24:16.053117');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('19b998e0-ece9-4c45-9872-342fb0daac25', 'Complete the test module', 'Unload the rdkv_stability test module after all iterations complete.', 'The test module should be unloaded cleanly and the final test status should reflect the observed results.', '3d529259-def7-4226-ac00-fc69d2c15385', '2026-10-07 08:24:16.053968', '2026-10-07 08:24:16.053969');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('58e9d9bd-5441-4592-a269-b3b9d776bed9', 'Subscribe to download and installation events', 'Register listeners for application download and installation status events using the following JSON-RPC payloads:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1f5b87fa-120b-4239-ac8a-bd56cafee592', 'Start the validation package download', 'Clear the event buffer and start downloading the configured large validation package.', 'The download request should return success and provide a download identifier.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.959420', '2026-10-07 07:52:05.959422');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('19873e8d-7a87-414a-b18d-ba7fea0a458e', 'Verify download identifier uniqueness', 'Compare the new download identifier with all identifiers recorded during the test and store it when it has not been used previously.', 'The download identifier should be unique and should be added to the recorded identifier set.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.960237', '2026-10-07 07:52:05.960238');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f9bea8a1-b63b-4aba-903a-5f5806c1f40f', 'Poll download progress', 'Query download progress using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Poll for up to 30 checks until progress becomes greater than zero.', 'The progress query should return successfully and should report a value greater than zero before cancellation.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.961781', '2026-10-07 07:52:05.961782');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('89a8ad88-1347-41a9-af99-c139cea0b755', 'Cancel the in-progress download', 'Cancel the download using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.cancel","params":{"downloadId":"<download_id>"}}.', 'The cancellation request should return success while the download is between 0 and 100 percent complete.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.963374', '2026-10-07 07:52:05.963375');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ee07f1f-5935-4488-8f8e-ee3cb41cf6d9', 'Verify replacement download identifier uniqueness', 'Add the replacement download identifier to the recorded identifiers and verify that no identifier has been reused.', 'The replacement download identifier should be unique.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.964219', '2026-10-07 07:52:05.964220');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('26ee4faa-82e4-462c-ba2d-fb5dec78cd57', 'Validate the cancellation event', 'Read the event buffer for up to 120 seconds and validate an onAppDownloadStatus event containing DOWNLOAD_FAILURE. Parse its download status and extract the event download identifier and file locator.', 'A cancellation event should be received, its identifier should match the cancelled download, and its file locator should be non-empty.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.965716', '2026-10-07 07:52:05.965716');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c32bdb7d-334f-4ea6-a64e-5d3b8421b2ad', 'Start the replacement application download', 'Clear the event buffer and start downloading the configured Google application bundle.', 'The replacement download request should return success and provide a new download identifier.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.966540', '2026-10-07 07:52:05.966553');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('10c82665-c13d-4b2c-9105-0f94999831b5', 'Validate replacement download completion', 'Read download status events for up to 120 seconds until an onAppDownloadStatus event without DOWNLOAD_FAILURE is received. Parse the event and compare its completed download identifier with the replacement download identifier.', 'A successful download event should be received, its identifier should match, and its file locator should be non-empty.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.967419', '2026-10-07 07:52:05.967420');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f385aa5e-b53a-4a5b-8e0d-bdb38e64e11c', 'Install the downloaded application', 'Submit the installation request using the replacement download file locator and the Google application name as the application identifier.', 'The installation request should return success and use the freshly downloaded file locator.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.968164', '2026-10-07 07:52:05.968165');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('46a8633d-aa3d-40bb-bdb9-ce6cb3dec763', 'Validate the installation event', 'Confirm that the cancellation event preceded the successful replacement download and installation flow, and verify that the number of recorded download identifiers equals the number of unique identifiers.', 'The event sequence should represent download cancellation followed by installation, and no download identifier should be reused.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.968994', '2026-10-07 07:52:05.968995');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('28d69f8d-ae36-48d3-9d1b-a3313f60cd07', 'Uninstall the application', 'Uninstall the Google application using its application identifier.', 'The uninstall request should return success and the application should be removed.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.969796', '2026-10-07 07:52:05.969797');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('051eb329-7761-4904-bb35-f5ba9c93736e', 'Repeat the download and installation validation', 'Repeat the download, progress polling, cancellation, cancellation-event validation, replacement download, completion-event validation, installation, installation-event validation, uniqueness checks, and uninstall actions for the configured application manager test count.', 'The complete event-order validation block should execute for every configured iteration, and each iteration should preserve unique download identifiers and the required event sequence.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.970605', '2026-10-07 07:52:05.970605');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('588517f1-9982-4985-99da-37a5cb189105', 'Disconnect the event listener', 'Disconnect the event listener and unload the rdkv_stability test module after all iterations complete.', 'The event listener and test module should be disconnected and unloaded cleanly.', '9bb559cd-ada3-4b7e-854f-12f5177a973a', '2026-10-07 07:52:05.972127', '2026-10-07 07:52:05.972128');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('55b530d7-bc58-4b17-ada9-2f67be60b4a4', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.692709', '2026-10-06 18:09:48.692710');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('34a1b369-12d2-49b4-89e6-0bbedfceb3fd', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.693832', '2026-10-06 18:09:48.693833');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('055ade54-f2ed-4b74-a654-0efc85165ca0', 'Build the direct Vorbis WebM player test URL', 'Combine the configured Vorbis WebM source URL, webm URL type, selected codec_webm player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete direct Vorbis WebM player test URL should be generated.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.694864', '2026-10-06 18:09:48.694865');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1f4fa09f-38d5-4917-a7ca-d358501a73e9', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated direct Vorbis WebM player test URL>"}}.', 'The direct Vorbis WebM player URL should be stored successfully in PersistentStore.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.695879', '2026-10-06 18:09:48.695880');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c11ec67d-04b2-4f7e-9d56-69a46a151235', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.697023', '2026-10-06 18:09:48.697024');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('254055a0-d758-4b18-a3e2-d21dbf9a36cf', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.697371', '2026-10-06 18:09:48.697372');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ca243fa3-0c11-43da-b00a-d1393a62e784', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.698375', '2026-10-06 18:09:48.698376');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5d90ac6a-e242-48ac-a8c9-cd022f229566', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.699396', '2026-10-06 18:09:48.699398');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('63596934-cad1-468b-8432-caa8d8687bb3', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.700449', '2026-10-06 18:09:48.700450');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c88e07bd-b6c6-4073-9695-59e8cf310a44', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.701497', '2026-10-06 18:09:48.701498');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ee86878e-c2d3-480a-bea3-08ac83ec3e96', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.702518', '2026-10-06 18:09:48.702520');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2e85ed55-cc2c-4d66-8ba4-fe0b76904cb1', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.703569', '2026-10-06 18:09:48.703570');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('72c72026-a1cb-4aad-b686-b52096f4b67d', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.704548', '2026-10-06 18:09:48.704549');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a996a3d8-5378-47e5-b433-53d95dc993ff', 'Calculate time to direct Vorbis playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.705480', '2026-10-06 18:09:48.705481');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6ba32c01-7327-494b-8fe9-a3b6ff8b6ecd', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to direct Vorbis playback should be within the configured threshold; otherwise the test should fail.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.705718', '2026-10-06 18:09:48.705719');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e5dc7231-33b1-46d8-a500-2187c3674eda', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.706569', '2026-10-06 18:09:48.706569');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b9c59be9-d213-4c6f-9946-91cafe2d0b5f', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.707402', '2026-10-06 18:09:48.707403');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3ba69ec0-040d-4ec1-a6a2-adf115a2cbb0', 'Record the execution summary and unload the module', 'Record the Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.summary and unload the module', 'The execution summary should be available and the test module should unload successfully.', 'ae27acf2-e432-433b-8531-f77d88a87763', '2026-10-06 18:09:48.708218', '2026-10-06 18:09:48.708219');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('25bdd909-98a6-4a6b-a817-13b5ae24f720', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.468545', '2026-09-08 07:20:16.468546');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e5b36263-f64f-4a96-8681-4d658266eebb', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('05bb4747-eb53-406d-b4cb-7d7de93b6748', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a69b3001-0912-4a87-a19c-4c17784d9d1f', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0b304fe6-e687-4ed0-9db1-1c786939bb8f', 'Load the first stream (DASH HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.471876', '2026-09-08 07:20:16.471878');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bfb99d07-4c99-4175-9636-beb6007768ba', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.472119', '2026-09-08 07:20:16.472121');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7a876afb-a15d-41c3-b638-78421d9df524', 'Clear the browser, load the second stream (4K HLS HEVC) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the 4K HLS HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the 4K HLS HEVC stream loads and media events are captured.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.473111', '2026-09-08 07:20:16.473112');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5d3e58aa-347c-4a59-8013-489dcbcec312', 'Validate observed events for the second playback and record intermediate result.', 'If the 4K HLS HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the 4K HLS HEVC playback.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.474001', '2026-09-08 07:20:16.474003');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c49524bc-5127-4d93-acf7-372522cc4b22', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH HEVC and 4K HLS HEVC playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'f3eb30f6-d692-4650-9ee0-684521f520b4', '2026-09-08 07:20:16.474985', '2026-09-08 07:20:16.474987');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8ddf3842-f734-439d-9e1c-6443d87d1ab5', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('73260bf0-3e6e-4073-87e7-987449cb1f68', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '12f8c237-1afb-498c-8f3d-f7ab59e359ad', '2026-10-06 10:50:35.634305', '2026-10-06 10:50:35.634306');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13fa8dcf-334a-4a90-b813-659100537f09', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7b0f965b-b7c7-48bf-b391-9d628f9160e5', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c0ec8e7f-0de6-44aa-bae3-53d98eb024b9', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('06560aa2-e76e-4089-96dd-8bad2558da1c', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '12f8c237-1afb-498c-8f3d-f7ab59e359ad', '2026-10-06 10:50:35.638579', '2026-10-06 10:50:35.638579');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ef9bbc43-e765-49cb-b903-5b082886c64c', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '12f8c237-1afb-498c-8f3d-f7ab59e359ad', '2026-10-06 10:50:35.639559', '2026-10-06 10:50:35.639560');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7a51dbbe-8de9-49ed-9dc6-cb75e0af830b', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a8fbac13-4d30-4221-b17b-cc91583acf76', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager.', 'The required application services should be activated successfully.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.653798', '2026-10-08 05:12:34.653799');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6ae19b52-2516-4860-a1ed-a18db30c96b6', 'Install the first application', 'Download and install the first configured application bundle without launching it.', 'The first application should be installed successfully.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.654074', '2026-10-08 05:12:34.654075');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb172e27-7f68-4a35-a945-bf85166248ae', 'Install the second application', 'Download and install the second configured application bundle without launching it.', 'The second application should be installed successfully, and its identifier should be distinct from the first application identifier.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.654388', '2026-10-08 05:12:34.654389');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1f3ec939-4220-49d6-a77d-96498069b9a6', 'Launch the first application', 'Submit a launch request for the first configured application.', 'The launch request should return success, and the first application should be present in the loaded-application list with an active state.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.655408', '2026-10-08 05:12:34.655409');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('72c4faeb-2e78-4449-bf43-9a6608b53bfc', 'Launch the second application', 'Submit a launch request for the second configured application.', 'The launch request should return success, and the second application should be present in the loaded-application list with an active state.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.655706', '2026-10-08 05:12:34.655718');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('465ca463-0593-475e-9ec7-2736e1010db9', 'Kill the first application', 'Kill the first application using the AppManager JSON-RPC method: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.killApp","params":{"appId":"<app_id_1>"}}.', 'The kill request should return success, and the first application should be absent from the loaded-application list.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.656008', '2026-10-08 05:12:34.656009');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7745191b-2424-436e-ac7a-91f508f24948', 'Kill the second application', 'Kill the second application using the AppManager JSON-RPC method: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.killApp","params":{"appId":"<app_id_2>"}}.', 'The kill request should return success, and the second application should be absent from the loaded-application list.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.656343', '2026-10-08 05:12:34.656344');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('257e840e-6e10-41dc-8110-73baf56ce407', 'Relaunch the first application', 'Submit a launch request for the first configured application a second time.', 'The launch request should return success, and the first application should be present in the loaded-application list with an active state.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.657342', '2026-10-08 05:12:34.657343');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('325a4d12-6d18-4a46-9775-6c6ce59ebe64', 'Relaunch the second application', 'Submit a launch request for the second configured application a second time.', 'The launch request should return success, and the second application should be present in the loaded-application list with an active state.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.658244', '2026-10-08 05:12:34.658245');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0685b481-c1fc-4034-9ce3-053f126b5417', 'Terminate the first application', 'Terminate the first application using its application identifier.', 'The termination request should return success, and the first application should be absent from the loaded-application list.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.659128', '2026-10-08 05:12:34.659129');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f69d37c1-5aba-4c40-ac59-83c1a1ce0507', 'Terminate the second application', 'Terminate the second application using its application identifier.', 'The termination request should return success, and the second application should be absent from the loaded-application list.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.659354', '2026-10-08 05:12:34.659354');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('efb038fc-2246-4fba-9a26-bf6cdaf68fd4', 'Repeat the multi-application lifecycle sequence', 'Repeat the launch, launch, kill, kill, launch, launch, terminate, and terminate actions, including loaded-application state validation after each action, for the configured application manager test count.', 'Every configured cycle should preserve the expected active or absent state for both applications, and any failed lifecycle request or state check should mark the cycle unsuccessful.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.659539', '2026-10-08 05:12:34.659540');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c5020d50-f5ad-4ffe-a268-0840b3971c39', 'Complete the test module', 'Unload the rdkv_stability test module after all lifecycle cycles complete.', 'The test module should be unloaded cleanly and the final test status should reflect the observed results.', 'd9537d04-7a67-4a05-aaa4-c03b287cd310', '2026-10-08 05:12:34.659735', '2026-10-08 05:12:34.659735');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d29fb0ec-ccbc-4d19-86d0-52b0ec855752', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.248368', '2026-10-08 05:05:28.248369');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6180d1be-3c57-4825-b25d-fe280e9eb4d6', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.248589', '2026-10-08 05:05:28.248590');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5f87b6ac-aedf-4063-ac55-7dca061609fc', 'Select the Vorbis codec player', 'Split codec_ogg into the configured player identifiers and use video_src_url_vorbis with the configured vp9_url_type.', 'The selected player list should correspond to the Vorbis source.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.249481', '2026-10-08 05:05:28.249482');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b3ee2129-58a8-4ec6-ae57-f61c09f1fbd0', 'Build the Vorbis player test URL', 'Combine the Vorbis source URL, configured URL type, selected codec_ogg player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete Vorbis player test URL should be generated.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.250305', '2026-10-08 05:05:28.250306');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9732d1af-2a24-4f2f-9c0e-e23fbaeb5edf', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated Vorbis player test URL>"}}.', 'The Vorbis player URL should be stored successfully in PersistentStore.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.250521', '2026-10-08 05:05:28.250522');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0bc28701-9238-4144-acac-38c74cc8bc8f', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.251432', '2026-10-08 05:05:28.251433');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('587b5931-0f6c-43cb-a682-bcd362ba4a70', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.252236', '2026-10-08 05:05:28.252237');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e0fbdad0-d4e2-4fe9-82d1-e542826c933d', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.252477', '2026-10-08 05:05:28.252478');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8b9fcc32-895a-4fc3-a75f-6719b1895c01', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.253395', '2026-10-08 05:05:28.253396');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6aff6eeb-9558-44c0-9e22-1969583ae16c', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.253599', '2026-10-08 05:05:28.253600');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6a3dfc31-1ba2-43d4-ab54-c16412889edf', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.253778', '2026-10-08 05:05:28.253779');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d9a3dfbb-4dd1-4828-abb3-008f7a5d52e9', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.254578', '2026-10-08 05:05:28.254579');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24721318-1a49-4853-813d-f023e9569672', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.254773', '2026-10-08 05:05:28.254774');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('28cef7cf-5680-4dc5-9d8f-fe407399d7c3', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.255592', '2026-10-08 05:05:28.255592');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1fd9b684-2ba6-4f0b-9b3f-1ae2fe6cce7e', 'Calculate time to Vorbis playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.255821', '2026-10-08 05:05:28.255822');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6335511-62b4-4231-bbf0-fc19f4a0a408', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to Vorbis playback should be within the configured threshold; otherwise the test should fail.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.256019', '2026-10-08 05:05:28.256020');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bc9833af-a02d-466f-8481-c51e8b18794c', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.256200', '2026-10-08 05:05:28.256200');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c428fa07-bddf-4e5a-a2c7-0962459436d0', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.256424', '2026-10-08 05:05:28.256425');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('06e2e3f6-7cf5-4a32-867e-5606ef1878f3', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '203cbae1-e591-4d6b-be9b-9d84a9e5fb81', '2026-10-08 05:05:28.259769', '2026-10-08 05:05:28.259770');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ace9ed2d-c069-4e58-a724-0abed070235b', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.513627', '2026-10-08 05:06:28.513628');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('21e5d6d0-903c-4469-9ae3-84405bb08a61', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.514489', '2026-10-08 05:06:28.514491');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('649f2692-3359-4196-9f9d-da6421e0f5cf', 'Select the VP9 codec player', 'Split codec_vp9 into the configured player identifiers and use video_src_url_vp9 with URL type vp9_url_type.', 'The selected player list should correspond to the VP9 source.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.515316', '2026-10-08 05:06:28.515317');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f1fc0618-d974-4fd0-9585-4d401f7caf25', 'Build the VP9 player test URL', 'Combine the VP9 source URL, configured URL type, selected codec_vp9 player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete VP9 player test URL should be generated.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.516445', '2026-10-08 05:06:28.516446');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3592b33e-97f5-464a-a9e4-77f372cd2bcc', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated VP9 player test URL>"}}.', 'The VP9 player URL should be stored successfully in PersistentStore.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.518022', '2026-10-08 05:06:28.518023');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('16c51861-14f3-4225-bb78-ac4d4f4d8f47', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.518590', '2026-10-08 05:06:28.518591');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('58641602-57e9-4329-ab1e-1bf44e065200', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.519242', '2026-10-08 05:06:28.519243');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8d5fc926-25c0-40a0-b469-388c126acc24', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.520534', '2026-10-08 05:06:28.520535');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4215e9be-d74e-4a0d-b022-144d4e22850e', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.521184', '2026-10-08 05:06:28.521185');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13a531c9-6888-4938-b690-4c0371a2b1b0', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.521538', '2026-10-08 05:06:28.521539');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d1b54b82-63f3-42f8-acc9-ec36f7e87a4b', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.522097', '2026-10-08 05:06:28.522098');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2d3c8808-d332-4089-9368-54fab9b76428', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.522738', '2026-10-08 05:06:28.522739');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('07c3f613-a4a3-4913-98dd-d82a664c9115', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.524465', '2026-10-08 05:06:28.524467');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f94f27f3-10bc-4c14-a185-c9b81df00d5b', 'Calculate time to VP9 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.525824', '2026-10-08 05:06:28.525825');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a5c2d5c1-027f-42d5-abe3-e4cabc369751', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to VP9 playback should be within the configured threshold; otherwise the test should fail.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.526751', '2026-10-08 05:06:28.526752');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ea5d9892-1289-4195-b773-d829b542fb15', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'd3d421b0-0324-456b-a56f-e7a63492c0d1', '2026-10-08 05:06:28.527152', '2026-10-08 05:06:28.527153');
