INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fe45eeda-a17f-4cfb-a463-1f1db4a48a42', 'Calculate time to video playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '5c95f56d-0cfb-43b8-83b6-ce91b6fa910a', '2026-10-08 04:53:35.589511', '2026-10-08 04:53:35.589511');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dad35a73-2d4e-4c6c-ad59-438a93bc01d1', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to 4K MKV video playback should be within the configured threshold; otherwise the test should fail.', '5c95f56d-0cfb-43b8-83b6-ce91b6fa910a', '2026-10-08 04:53:35.590388', '2026-10-08 04:53:35.590389');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('52e05008-6590-48f2-8c6b-ea16b3efd0b6', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '5c95f56d-0cfb-43b8-83b6-ce91b6fa910a', '2026-10-08 04:53:35.591272', '2026-10-08 04:53:35.591273');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('643818ae-1aa9-4006-8f18-8fe1546ddc63', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '5c95f56d-0cfb-43b8-83b6-ce91b6fa910a', '2026-10-08 04:53:35.592114', '2026-10-08 04:53:35.592115');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('50762063-71eb-4f4d-8119-cabf86e0fe7a', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '5c95f56d-0cfb-43b8-83b6-ce91b6fa910a', '2026-10-08 04:53:35.592961', '2026-10-08 04:53:35.592962');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5b382d25-9701-4fce-9a8b-ee3c1ece35dc', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager.', 'The required application services should be activated successfully.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.516910', '2026-10-07 08:07:01.516911');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e7cc0af8-620e-41d9-be14-fcbfb95b87d6', 'Subscribe to the uninstall event', 'Register for the AppManager uninstall event using: {"jsonrpc": "2.0","id": 1,"method": "org.rdk.AppManager.1.register","params": {"event": "onAppUninstalled", "id": "client.events.1" }}.', 'The onAppUninstalled event subscription should be registered successfully.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.519199', '2026-10-07 08:07:01.519200');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b480c964-418c-462f-a700-7f1e7c7d56c3', 'Install the application under test', 'Download and install the configured Google application bundle for com.rdkcentral.google without launching it.', 'The application should be installed successfully and should be available for state validation.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.527409', '2026-10-07 08:07:01.527410');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e529273c-a7ef-4bb3-a5be-9b13ee0a6973', 'Capture the initial installed-applications snapshot', 'Query installed applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getInstalledApps","params":{}}.', 'The query should return success and the initial snapshot should contain com.rdkcentral.google.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.528359', '2026-10-07 08:07:01.528360');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6af04a9c-4ba0-4dc0-a98a-0459ed7d27ac', 'Check the initial installation state', 'Query the application installation state using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.isInstalled","params":{"appId":"com.rdkcentral.google"}}.', 'The query should return success and indicate that com.rdkcentral.google is installed.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.529185', '2026-10-07 08:07:01.529186');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8505800e-8095-4abe-9c0a-e42f14910490', 'Capture the initial loaded-applications snapshot', 'Query loaded applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps","params":{}}.', 'The query should return success and the application should not be loaded before launch.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.529996', '2026-10-07 08:07:01.529997');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('08c904c2-9841-4fd0-9263-7a8a49be4946', 'Launch the application', 'Submit a launch request for com.rdkcentral.google.', 'The launch request should return success.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.530788', '2026-10-07 08:07:01.530789');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5c29d738-3c2a-40f1-9f41-42451c4388b3', 'Terminate the application', 'Terminate the launched application using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.terminateApp","params":{"appId":"com.rdkcentral.google"}}.', 'The termination request should return success.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.531685', '2026-10-07 08:07:01.531686');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0d79286d-6d85-4719-92d2-c33bc672125e', 'Uninstall the terminated application', 'Submit an uninstall request for com.rdkcentral.google.', 'The uninstall request should return success.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.532507', '2026-10-07 08:07:01.532508');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4f7c025b-3b33-4f87-9876-254374aea94f', 'Validate the uninstall event', 'Read the event buffer for up to 120 seconds until an event containing onAppUninstalled and com.rdkcentral.google is received.', 'The onAppUninstalled event should be received for the expected application.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.533365', '2026-10-07 08:07:01.533366');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ebd614cc-a625-4d05-9130-a3ef48251e7e', 'Capture the final installed-applications snapshot', 'Query installed applications again using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getInstalledApps","params":{}}.', 'The query should return success and the final snapshot should not contain com.rdkcentral.google.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.534157', '2026-10-07 08:07:01.534158');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5e31068f-fb92-406f-be68-e7e880646581', 'Check the final installation state', 'Query the final installation state using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.isInstalled","params":{"appId":"com.rdkcentral.google"}}.', 'The query should return success and indicate that com.rdkcentral.google is not installed.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.534979', '2026-10-07 08:07:01.534980');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fec53735-3a40-4832-923d-8890fa01a6fa', 'Capture the final loaded-applications snapshot', 'Query loaded applications again using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps","params":{}}.', 'The query should return success and the final snapshot should not contain com.rdkcentral.google.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.535811', '2026-10-07 08:07:01.535812');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2ccecf68-3a94-48e0-84d4-d66600832c7f', 'Verify cross-surface state consistency', 'Compare the initial and final installed-applications snapshots, isInstalled results, loaded-applications snapshots, and the uninstall event. The initial state must be installed, reported as installed, and not loaded; the final state must be absent from all query surfaces and accompanied by the matching uninstall event.', 'All query surfaces and the event stream should agree on the application state before and after uninstall.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.536703', '2026-10-07 08:07:01.536703');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('55a10691-2962-4d69-88dc-a0f9a25b7097', 'Reinstall the application for the next iteration', 'Reinstall the configured application bundle without launching it before beginning the next iteration.', 'The application should be installed successfully and ready for the next consistency check.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.537527', '2026-10-07 08:07:01.537528');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7eb3507d-19bc-4d6e-ac20-e601d15bfc8e', 'Repeat the state-consistency validation', 'Repeat the initial snapshots, launch, termination, uninstall, event validation, final snapshots, consistency comparison, and reinstall actions for the configured application manager test count.', 'Every configured iteration should maintain consistent installed, loaded, and event states across the uninstall transition.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.538419', '2026-10-07 08:07:01.538420');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6f6e225b-355a-4c13-989d-44984ac7b624', 'Disconnect the event listener and test module', 'Disconnect the uninstall event listener and unload the rdkv_stability test module after all iterations complete.', 'The event listener and test module should be disconnected and unloaded cleanly.', 'b089a4d7-304c-42aa-a718-c3684ffddba8', '2026-10-07 08:07:01.539310', '2026-10-07 08:07:01.539311');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('39997204-44d3-48cb-b1a8-f5bb6dd06673', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '1eb3838e-eaeb-4ce4-ae7b-815d6a3ac84b', '2026-10-06 10:48:35.522071', '2026-10-06 10:48:35.522072');
