INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b3989b6c-6eba-4c22-a909-1d0a5570a832', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '1eb3838e-eaeb-4ce4-ae7b-815d6a3ac84b', '2026-10-06 10:48:35.526500', '2026-10-06 10:48:35.526501');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd7774a9-390f-49db-b329-b75bfe45f4c2', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '1eb3838e-eaeb-4ce4-ae7b-815d6a3ac84b', '2026-10-06 10:48:35.527408', '2026-10-06 10:48:35.527409');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('21875de3-fc0e-4013-9b5a-2c90401abb3e', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c2356e7d-88ed-48da-ab6a-b3c238a8cd25', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.040092', '2026-09-08 07:18:04.040097');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a18c2cf-70e5-412f-afb7-c590e42f527f', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
