INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9b857927-f527-4cd8-b552-0b71f64011fa', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ee686798-a0e8-43bb-99e5-acc5d115934b', 'Load the first stream (4K HLS HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the 4K HLS HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the 4K HLS HEVC playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.042426', '2026-09-08 07:18:04.042428');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2e30c61e-4184-4ce8-995e-16d4794e5a39', 'Validate observed events for the first playback and record intermediate result.', 'If the 4K HLS HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the 4K HLS HEVC playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.043524', '2026-09-08 07:18:04.043526');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('70f78166-3100-4fc8-b63b-98ed234b167b', 'Clear the browser, load the second stream (HLS H264) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HLS H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HLS H264 stream loads and media events are captured.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.044693', '2026-09-08 07:18:04.044696');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3e2f0a65-beb1-485a-ba31-4ff540917df7', 'Validate observed events for the second playback and record intermediate result.', 'If the HLS H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the HLS H264 playback.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.045803', '2026-09-08 07:18:04.045806');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('16e650f4-6eee-4c13-9bd5-5edf7cd1ebe6', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the 4K HLS HEVC and HLS H264 playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '949d9ae5-a73d-49a9-90ed-00a717b036f4', '2026-09-08 07:18:04.046806', '2026-09-08 07:18:04.046808');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4fbea339-2566-40eb-ab91-4d2946bbba48', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a9ecbb4b-84b6-409d-b145-627c29d0ce10', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', '2742623e-a27c-4316-b810-ab078c7bb3cb', '2026-09-08 07:11:19.680832', '2026-09-08 07:11:19.680835');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cbea6133-34ab-45e2-9c42-0b7b3873edb7', 'Test Step 2', 'The application starts playing a Widevine DRM-protected AV1 DASH stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The DASH AV1 stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', '2742623e-a27c-4316-b810-ab078c7bb3cb', '2026-09-08 07:11:19.681219', '2026-09-08 07:11:19.681221');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('240a4a7c-5f75-4ef9-89f9-c5093287b794', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', '2742623e-a27c-4316-b810-ab078c7bb3cb', '2026-09-08 07:11:19.681617', '2026-09-08 07:11:19.681619');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a23d5b2-0eaf-450c-b94c-efd453234262', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', '2742623e-a27c-4316-b810-ab078c7bb3cb', '2026-09-08 07:11:19.681988', '2026-09-08 07:11:19.681990');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb4e7402-0d2f-4a86-b2a1-f5c052d3f7a0', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', '2742623e-a27c-4316-b810-ab078c7bb3cb', '2026-09-08 07:11:19.683069', '2026-09-08 07:11:19.683071');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('23711c13-82e6-4426-87b4-8e3f95e440d7', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.637420', '2026-09-08 07:20:58.637422');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('578de07d-4bb5-4c9e-a8e0-0857a06e8f7f', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
