INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6eb1f362-c4c6-4c7c-9a12-b467a1f38741', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0a9a681d-3901-4415-adf8-8006d8dc6c5c', 'Load the first stream (DASH HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH HEVC playback.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.641793', '2026-09-08 07:20:58.641794');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('baff4bbb-ba8a-4b66-b6af-3f87e0d37b64', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.642049', '2026-09-08 07:20:58.642050');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8cdeca8c-d03a-48cd-b4fe-8e01f491e207', 'Clear the browser, load the second stream (HEVC MKV) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HEVC MKV stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HEVC MKV stream loads and media events are captured.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.643001', '2026-09-08 07:20:58.643003');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3a69a06c-fa8b-4a09-b954-6e44ada84988', 'Validate observed events for the second playback and record intermediate result.', 'If the HEVC MKV stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the HEVC MKV playback.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.643897', '2026-09-08 07:20:58.643898');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e0aef5a7-4648-40e0-b8ed-e006a1650d84', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH HEVC and HEVC MKV playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '96d5bcaa-b823-4ae7-ad4d-d53053fc298f', '2026-09-08 07:20:58.644134', '2026-09-08 07:20:58.644135');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ce1b1a89-fd8f-427a-b399-ac9b9f71b8aa', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0b172f04-6f69-4333-b297-117d4c860b87', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', '31e0a774-d8b4-4655-9d04-3255d8164d31', '2026-09-08 07:12:22.611213', '2026-09-08 07:12:22.611215');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f6919023-431c-48c9-ba87-a963da8841f7', 'Test Step 2', 'The application starts playing a Widevine DRM-protected VP9 OPUS DASH stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The DASH VP9 OPUS stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', '31e0a774-d8b4-4655-9d04-3255d8164d31', '2026-09-08 07:12:22.611606', '2026-09-08 07:12:22.611608');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bc554afd-5087-476f-bc24-35252d9ce7b2', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', '31e0a774-d8b4-4655-9d04-3255d8164d31', '2026-09-08 07:12:22.611973', '2026-09-08 07:12:22.611975');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cb72326c-f74f-4037-a566-5959f26bdfda', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', '31e0a774-d8b4-4655-9d04-3255d8164d31', '2026-09-08 07:12:22.613001', '2026-09-08 07:12:22.613003');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c9e12ade-e8c6-4665-9dfa-c602d7bb36c7', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', '31e0a774-d8b4-4655-9d04-3255d8164d31', '2026-09-08 07:12:22.614007', '2026-09-08 07:12:22.614009');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0daf9aba-a51c-4752-873d-db06a2a6e449', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'c15bfb6e-2b92-4b84-b7cc-0ad4dd41b545', '2026-10-05 09:04:30.836679', '2026-10-05 09:04:30.836681');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('85ad780a-985b-4405-9aa1-f7272791f303', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b65466c5-a814-4021-a0a4-1a42509b451f', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3803ed9e-a7dd-4229-9cc2-c34ac2f06bc7', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('19ccae26-bb32-46e6-b8f2-43b9cbb417c4', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'c15bfb6e-2b92-4b84-b7cc-0ad4dd41b545', '2026-10-05 09:04:30.841181', '2026-10-05 09:04:30.841183');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a436fe69-5843-4d7c-a242-b113818b3c60', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'c15bfb6e-2b92-4b84-b7cc-0ad4dd41b545', '2026-10-05 09:04:30.842108', '2026-10-05 09:04:30.842109');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('94ab20fb-6a40-49ce-812d-0603f6f01401', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('492eb8a7-ce8b-4423-98f9-85c1f5d8e215', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_SetZOrder_GetZOrder.', 'The performance test module should load successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.863684', '2026-09-08 06:27:49.863687');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6156ad5b-6590-4b48-86f4-8ae49be15562', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.864689', '2026-09-08 06:27:49.864692');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6e354120-e8de-43f2-99e2-9e6c4fa7f974', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the application; otherwise download and install it.', 'The installed-package query should complete successfully, and the application installation state should be determined.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.865788', '2026-09-08 06:27:49.865792');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b2dcf279-3751-49f6-af98-4eb8f3a9185d', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.866844', '2026-09-08 06:27:49.866849');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5b9c3ae8-7e19-44e0-8b53-c19bae1fa610', 'Install the application bundle when required', 'Install the downloaded bundle using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.867855', '2026-09-08 06:27:49.867859');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d737d7b7-1ef4-4212-bcd7-1e223e160935', 'Install the application bundle when required', 'Install the downloaded bundle using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.868219', '2026-09-08 06:27:49.868223');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('221b706b-3826-468c-a5fe-9e8047301ce4', 'Verify the application installation', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the application ID is listed.', 'The application ID should appear in the installed package list.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.869325', '2026-09-08 06:27:49.869328');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('669b0397-de0e-4855-aa7b-561e5076e885', 'Launch the application', 'Launch the application using org.rdk.AppManager.launchApp with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<app_id>","intent":"","launchArgs":""}}.', 'The application should launch successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.870298', '2026-09-08 06:27:49.870301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5af38779-0a07-455e-9c5f-a306995780e1', 'Retrieve the active application instance ID', 'Query loaded applications using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"}. Select the entry whose appId is the target application and whose lifecycleState is APP_STATE_ACTIVE, and obtain its appInstanceId.', 'An active application entry should be returned with a non-empty application instance ID.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.871405', '2026-09-08 06:27:49.871410');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5b37423c-29bd-4a5e-9a49-df733da7d495', 'Set the application z-order', 'Set the requested z-order using org.rdk.RDKWindowManager.setZOrder with {"jsonrpc":"2.0","id":1,"method":"org.rdk.RDKWindowManager.setZOrder","params":{"clientId":"<app_instance_id>","zOrder":<requested_zorder>}}.', 'The z-order request should return success.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.872747', '2026-09-08 06:27:49.872751');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('de20503b-c40c-4a61-8ded-37d2af34d1be', 'Read back the application z-order', 'Query the assigned z-order using org.rdk.RDKWindowManager.getZOrder with {"jsonrpc":"2.0","id":1,"method":"org.rdk.RDKWindowManager.getZOrder","params":{"clientId":"<app_instance_id>"}}.', 'The get-z-order request should return success and a numeric z-order value.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.873129', '2026-09-08 06:27:49.873133');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3b65331c-c11e-4c29-ab37-ec5097f7ebe6', 'Compare the requested and returned z-order', 'Compare the value returned by getZOrder with requested_zorder.', 'The returned z-order should exactly match the requested z-order.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.874446', '2026-09-08 06:27:49.874449');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0dbc06f8-4859-4757-922d-f30904591c8e', 'Terminate the application', 'Terminate the application using {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<app_id>"}}.', 'The application should terminate successfully.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.876269', '2026-09-08 06:27:49.876273');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2333c268-ebaa-47db-b658-2697ed31c3e8', 'Unload the performance test module', 'Unload the RDKV performance test module after completing the z-order validation.', 'The performance test module should unload cleanly.', '475d9a2f-0f31-4f1d-b7de-ded26116031a', '2026-09-08 06:27:49.877415', '2026-09-08 06:27:49.877419');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5e6dc8e9-0555-4723-abf6-85f68a70fd4a', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager.', 'The required application services should be activated successfully.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.910054', '2026-10-07 07:38:02.910056');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6f20e253-4c99-4813-8754-800414944b16', 'Install the configured applications', 'For each configured application bundle, check its installation state, download the package when required, install the package, and verify the resulting installation.', 'Every configured application should be installed successfully.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.914241', '2026-10-07 07:38:02.914243');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('17798978-b187-4ef8-9991-b0a19163b219', 'Record the installed application set', 'Record the application names obtained from the configured application bundles as the expected installed application set.', 'The expected application set should contain all configured applications.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.915728', '2026-10-07 07:38:02.915729');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('57222c06-d5d4-429c-a71f-822ba28957ca', 'Clear data for all applications', 'Request removal of application data for all applications using the AppManager JSON-RPC method: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.clearAllAppData","params":{}}.', 'The clear-all-data request should return success, and application data should be cleared without removing installed applications.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.916536', '2026-10-07 07:38:02.916537');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ec29642-d49c-44d1-ab01-fe18375b749c', 'Retrieve the installed application set', 'Query the installed applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getInstalledApps","params":{}}.', 'The installed application query should return success.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.917463', '2026-10-07 07:38:02.917464');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7572a7ac-f3e6-464f-8058-93f996a564b2', 'Verify installed applications remain present', 'Compare the returned installed application set with the recorded application names and identify any missing applications.', 'No configured application should be missing after application data is cleared.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.918354', '2026-10-07 07:38:02.918355');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d7e1b1f1-87d7-4384-a978-06c76aaceaa2', 'Launch each installed application', 'For each configured application, submit the application launch request with the application name as the app_name parameter.', 'Each launch request should return success.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.919227', '2026-10-07 07:38:02.919228');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('65423460-a7f2-40e1-a5c9-2cceded67c93', 'Verify application loading', 'After each launch, read the device loaded-application list and verify that the launched application is present.', 'Each application should appear in the loaded-application list after launch.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.920108', '2026-10-07 07:38:02.920108');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b3e415b2-215d-4f75-93d1-83110c49c4ca', 'Terminate each launched application', 'Terminate the launched application using its application name as the app_id parameter.', 'Each application should terminate successfully.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.920954', '2026-10-07 07:38:02.920955');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ae72c8f-618f-40fb-95a6-796e6e9c9420', 'Validate resource usage', 'Request resource-usage validation after application termination.', 'Resource usage should be reported within the expected limit and should not return an error.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.921796', '2026-10-07 07:38:02.921797');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6d01c9ea-2614-40cb-a528-495e7edfb83d', 'Repeat the stability action block', 'Repeat the clear-all-data, installed-application verification, per-application launch verification, termination, and resource-usage validation actions for the configured application manager test count.', 'The complete action block should execute for every configured iteration, and any failure should mark the corresponding iteration as unsuccessful.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.922706', '2026-10-07 07:38:02.922707');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b8700b97-10f2-4377-bb52-efd234ea3953', 'Complete the test module', 'Unload the rdkv_stability test module after the test flow completes.', 'The test module should be unloaded cleanly and the final test status should reflect the observed results.', 'e332ba37-5834-49dd-acbb-249a49cd02ea', '2026-10-07 07:38:02.923575', '2026-10-07 07:38:02.923575');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b776c20f-a039-4932-9298-43b5fe2fe7a3', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'e4c4c04f-6cbf-4198-893f-c55733e0ad96', '2026-10-05 09:02:44.419834', '2026-10-05 09:02:44.419836');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('37122fb3-d4c9-4ea0-9745-d049a1bf8103', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c62dc6a0-59fa-4f0f-9bda-78d73555ef47', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('18cce3ba-a19a-4271-85d9-1dcacede6c72', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1b824022-2056-4d84-b880-b384c7e74599', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'e4c4c04f-6cbf-4198-893f-c55733e0ad96', '2026-10-05 09:02:44.425160', '2026-10-05 09:02:44.425162');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ecd44a8-c176-4413-9db3-e02447171df5', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'e4c4c04f-6cbf-4198-893f-c55733e0ad96', '2026-10-05 09:02:44.426174', '2026-10-05 09:02:44.426176');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('221ed858-a8d8-4b05-9a01-6f2016a3a14b', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ed4cce57-fade-413f-86c4-1084f22ca8c2', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.530066', '2026-09-08 07:19:34.530067');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0fb91322-9bba-47b0-9062-588f67083f62', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2913e21a-f784-4745-93c4-ff0d3d3eb989', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('342b8e20-4ca1-4f29-8d9b-398741a34c78', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f7affdff-016c-4022-8b2b-8055688b40db', 'Load the first stream (DASH H264) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH H264 playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.532664', '2026-09-08 07:19:34.532666');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d77d5949-f2d0-43f7-883f-6f8e5d7a6ded', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.533031', '2026-09-08 07:19:34.533033');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8364cc6a-80a3-4a8b-b1f8-b4f64f25c0dd', 'Clear the browser, load the second stream (DASH HEVC) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH HEVC stream loads and media events are captured.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.533409', '2026-09-08 07:19:34.533411');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8362867c-fa22-4896-9bec-adb647384fce', 'Validate observed events for the second playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.533771', '2026-09-08 07:19:34.533773');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a57fcb3e-a96d-47e0-ab54-4d2431493952', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH H264 and DASH HEVC playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'da9c18fd-cd29-40e8-be6d-896a9721da50', '2026-09-08 07:19:34.535014', '2026-09-08 07:19:34.535017');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('88cf3bc1-462a-4c09-affa-d768b59c9199', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0fc7c934-2783-4591-bad0-a13d3b6cb6bb', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '0c376b56-5c1a-4753-9488-8e72da7e6270', '2026-10-05 10:38:15.738449', '2026-10-05 10:38:15.738451');
