INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('501456d5-7920-4ceb-a90d-38a76fccd092', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b7404046-0d32-44a9-838f-8fbb458a28fe', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '0c376b56-5c1a-4753-9488-8e72da7e6270', '2026-10-05 10:38:15.745375', '2026-10-05 10:38:15.745377');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f11db46a-7611-44e6-8780-9aaa96cba002', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '0c376b56-5c1a-4753-9488-8e72da7e6270', '2026-10-05 10:38:15.746488', '2026-10-05 10:38:15.746491');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('12601c67-be2c-4899-8a03-cd3b6c39494e', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8f012464-6550-4f75-9427-0bec80432a13', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.495940', '2026-10-08 04:54:29.495941');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cf3f365f-0fc2-4175-b793-7ac4f34775d4', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.496157', '2026-10-08 04:54:29.496158');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1c47ffae-e29f-469a-afee-a5c5ebe98dad', 'Build the 4K VP9 player test URL', 'Combine the configured 4K VP9 source URL, VP9 URL type, selected codec/player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete 4K VP9 player test URL should be generated.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.497005', '2026-10-08 04:54:29.497006');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('be7e8ed5-fe6d-4e6b-823d-b35aedd3deb1', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated 4K VP9 player test URL>"}}.', 'The 4K VP9 player URL should be stored successfully in PersistentStore.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.497192', '2026-10-08 04:54:29.497192');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c8f0c124-f68f-4c16-8b5c-81e644265975', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.498049', '2026-10-08 04:54:29.498050');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('0ffb5e93-4ad2-4d1b-ae54-b11ff2f9cf59', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.498229', '2026-10-08 04:54:29.498230');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5aced692-a8eb-49e5-8646-759ad8c6d4e1', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.498442', '2026-10-08 04:54:29.498442');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('55b35cc8-8192-47cd-af2b-532daccb640e', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.500084', '2026-10-08 04:54:29.500085');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f7699281-8ed0-4f41-adfb-a3b1855d1b6b', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.500913', '2026-10-08 04:54:29.500914');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('421651e6-d47b-4835-8424-6eb623e0cdcb', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.501667', '2026-10-08 04:54:29.501668');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d8c2ad63-2b2e-465b-b43d-10d70b895994', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.501847', '2026-10-08 04:54:29.501847');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2a910560-51e5-49db-91fa-687375e2cc32', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.502633', '2026-10-08 04:54:29.502634');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7d68d42f-d3e7-499b-b8cd-74527999a515', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.504092', '2026-10-08 04:54:29.504093');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fa254c47-d80d-4f1f-ae46-0038b1a09b67', 'Calculate time to video playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.504867', '2026-10-08 04:54:29.504868');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('137d8c42-f2fa-4253-9bad-a8afc06c091f', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to 4K VP9 video playback should be within the configured threshold; otherwise the test should fail.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.505051', '2026-10-08 04:54:29.505052');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c92626d9-5b6c-4f7a-8ab9-3c2439646365', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.505841', '2026-10-08 04:54:29.505841');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('29e33e38-775e-425d-b408-70d733944991', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.506059', '2026-10-08 04:54:29.506060');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('49dc41e4-ade7-4c9f-8520-9ddbdb9bed41', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '48d395a4-3f29-4a7b-80ed-2a8d4d26095b', '2026-10-08 04:54:29.506263', '2026-10-08 04:54:29.506264');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6b356b3c-1c84-44bc-8f54-9412e90d67e5', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.197867', '2026-10-06 17:41:46.197869');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3338e0aa-fb3a-4d45-bb38-3cb224780540', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.199497', '2026-10-06 17:41:46.199498');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3369cb41-d6d3-442d-ae46-6865ff6227ce', 'Build the AC3 player test URL', 'Combine the configured AC3 source URL, AC3 URL type, the selected codec_ac3 player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete AC3 player test URL should be generated.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.200396', '2026-10-06 17:41:46.200397');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8e23e32f-69f5-4106-9c9d-6bd831f550f9', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated AC3 player test URL>"}}.', 'The AC3 player URL should be stored successfully in PersistentStore.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.201242', '2026-10-06 17:41:46.201243');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('76b8a79f-87d7-4e3d-9939-0af083f686e5', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.201501', '2026-10-06 17:41:46.201502');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('12e2177a-b553-4b5c-99c5-653040215b29', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.202300', '2026-10-06 17:41:46.202301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d8a2827b-08e1-4d6a-8a38-b06d1f9bd85c', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.203223', '2026-10-06 17:41:46.203224');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5f1091f9-6f1b-4759-8fc2-91bbedbe0f47', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.204238', '2026-10-06 17:41:46.204238');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('93eeb460-3c7f-402f-acad-6e0c9ed3a830', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.205391', '2026-10-06 17:41:46.205393');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1d3fcc4e-aad5-4a14-9bd2-e225df6e2d16', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.206307', '2026-10-06 17:41:46.206308');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b0fb6de9-6f40-4ebe-b200-e72003dc8891', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.206539', '2026-10-06 17:41:46.206540');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1060d6ce-8bb5-4310-be30-9648fd0ce0e3', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.207366', '2026-10-06 17:41:46.207367');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('607e53b7-cd15-46df-a9f0-8ea6cc99c8d2', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.208877', '2026-10-06 17:41:46.208878');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('97223e35-a582-4845-8380-9c8eacd9bb00', 'Calculate time to AC3 playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.209100', '2026-10-06 17:41:46.209101');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2e757907-5c15-4a12-947f-5e02a853f115', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to AC3 playback should be within the configured threshold; otherwise the test should fail.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.209914', '2026-10-06 17:41:46.209915');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd3dc832-ee58-4c83-a82d-b46fa3500aef', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.210957', '2026-10-06 17:41:46.210958');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5cb43238-b9e3-4ec7-8942-dda1448bf95b', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.212110', '2026-10-06 17:41:46.212111');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('eb8a0ac2-cb4a-41ec-9eca-abd18c40f4e0', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'dc83592e-9bef-41c8-996f-8919fe44c012', '2026-10-06 17:41:46.212452', '2026-10-06 17:41:46.212453');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cf2519fc-b34b-4d6f-9413-aa122a25b702', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'b0226911-ed17-4193-8628-52d2543f17b8', '2026-10-06 07:26:10.208848', '2026-10-06 07:26:10.208852');
