INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('59d48d93-9ef6-4156-b2aa-264206e35f79', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'd8e49cd9-7621-4139-b602-26f764632862', '2026-10-08 05:02:28.814176', '2026-10-08 05:02:28.814177');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24e8ca44-b1c9-4265-9a0a-f2d3c81e4900', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'd8e49cd9-7621-4139-b602-26f764632862', '2026-10-08 05:02:28.814398', '2026-10-08 05:02:28.814399');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fc50768c-05f8-419f-acb3-bb0d332af098', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'd8e49cd9-7621-4139-b602-26f764632862', '2026-10-08 05:02:28.814590', '2026-10-08 05:02:28.814591');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b12081bd-eeb8-456b-b579-e70b3fc0066c', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Download_Resume_Lifecycle.', 'The performance test module should load successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.510602', '2026-09-08 06:29:51.510606');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8c249cdf-3bb5-43e7-a627-e4853e5ab48f', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.512453', '2026-09-08 06:29:51.512458');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a009396a-5cdf-44f3-bc94-e41d0d425104', 'Construct the application download URL', 'Combine the configured app_download_url with Large_Validation_File to form the bundle URL.', 'The resulting download URL should identify the configured large validation bundle.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.513729', '2026-09-08 06:29:51.513733');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('41b31441-4009-4526-8acc-e12e954ef96c', 'Start the application bundle download', 'Request the download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url><Large_Validation_File>"}}.', 'The download request should return success and a valid download ID.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.514774', '2026-09-08 06:29:51.514778');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('577cc65e-388c-4c1b-8e66-cca829ad8951', 'Poll for active download progress', 'For up to progress_wait_time one-second attempts, query the download percentage using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Stop polling when the returned numeric value is greater than 0 and less than 100.', 'The download should reach an active in-progress state with a numeric percentage satisfying 0 < progress < 100.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.515272', '2026-09-08 06:29:51.515275');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13733b6a-11cb-4179-94f0-1b471076c6ff', 'Pause the active download', 'Pause the download using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.pause","params":{"downloadId":"<download_id>"}}.', 'The pause request should return success.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.516368', '2026-09-08 06:29:51.516372');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b925ce4f-fb8a-40b8-86f8-ce0ff4e25808', 'Read progress after pausing', 'Wait 3 seconds, then query progress again using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Compare the returned value with the progress recorded before pausing.', 'The progress value after the pause should equal the value recorded before the pause, demonstrating that downloading is suspended.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.517405', '2026-09-08 06:29:51.517408');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('39c6aeb3-626c-4696-8f5d-5d76a1f5ddfe', 'Read progress after resuming', 'Wait 5 seconds, then query progress using {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Compare the returned value with the paused progress value.', 'The resumed progress should be numeric and greater than the paused progress, demonstrating that downloading has continued.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.518431', '2026-09-08 06:29:51.518435');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('71def300-8c62-4229-8b99-a65050777a38', 'Complete the pause and resume lifecycle validation', 'Mark the test successful only when the pause request succeeds, progress remains unchanged while paused, the resume request succeeds, and progress advances after resuming.', 'The complete download pause-and-resume lifecycle should be validated successfully.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.519423', '2026-09-08 06:29:51.519426');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('df18e421-cefc-48da-9906-f7ead81efa61', 'Unload the performance test module', 'Unload the RDKV performance test module after the lifecycle checks finish.', 'The performance test module should unload cleanly.', 'debaa6fb-b774-4d65-9124-072af050b69f', '2026-09-08 06:29:51.520437', '2026-09-08 06:29:51.520440');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('71d68ac7-10af-4268-9272-1ce6cfe70493', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.318359', '2026-09-08 07:19:55.318360');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a13d92c0-b0d1-44e2-907a-9ac27643b94a', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('db116bc1-c962-4b56-b6e2-204f700ef02e', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('86fac66d-c1cc-43e7-b78e-74eae36ed24d', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ebbc08cd-6b3e-4f3d-b79e-9643affaf818', 'Load the first stream (DASH H264) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH H264 playback.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.321501', '2026-09-08 07:19:55.321503');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f0fd741-4800-43eb-8f77-e7d5f0e8217e', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH H264 playback.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.322413', '2026-09-08 07:19:55.322415');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd639462-4150-493d-871e-db9f3c5ab557', 'Clear the browser, load the second stream (HLS H264) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HLS H264 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HLS H264 stream loads and media events are captured.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.323306', '2026-09-08 07:19:55.323308');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5a51b8bc-a14c-4e28-815b-2ed35a281398', 'Validate observed events for the second playback and record intermediate result.', 'If the HLS H264 stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the HLS H264 playback.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.323597', '2026-09-08 07:19:55.323599');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c7a5fa10-757d-4db6-ab08-7117b5b883f0', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH H264 and HLS H264 playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '907a4ece-f2b0-4f16-a856-5fcf80f3aaf5', '2026-09-08 07:19:55.324507', '2026-09-08 07:19:55.324509');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('13b287c0-4be1-4542-ae69-62863e8ef5e3', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9a4e28d0-b028-4660-b4b8-83e07387d44a', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '68b725f9-250f-4f9f-a1e0-f13795ee5111', '2026-10-06 07:23:58.580925', '2026-10-06 07:23:58.580927');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d4535ce3-897e-40eb-bb40-b956dffc2e33', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f804114-5fbb-4d32-84ce-8945433f4f6f', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('141ae75f-8766-428c-9b53-55a8f8366988', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f0ff40d-436a-4dae-83be-ee73201131c9', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '68b725f9-250f-4f9f-a1e0-f13795ee5111', '2026-10-06 07:23:58.584886', '2026-10-06 07:23:58.584889');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ff965847-b3e5-4bbf-b1dc-6822be5bf379', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '68b725f9-250f-4f9f-a1e0-f13795ee5111', '2026-10-06 07:23:58.587191', '2026-10-06 07:23:58.587193');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('58402299-fe46-4203-8d1e-8049307f02a0', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('17700943-4ce2-4e41-bed3-6ade41b20e76', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.436386', '2026-10-08 05:03:41.436388');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b023f66f-36ea-4608-876b-60507363b49b', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.437297', '2026-10-08 05:03:41.437298');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9630bee2-0f33-47de-8f54-12b3c0e8731b', 'Select the HEVC codec player list', 'Select codec_hls_hevc when hevc_url_type is hls, codec_dash_hevc when it is dash, or codec_mp4 for other configured types, then split the selected codec list into player identifiers.', 'The player list should match the configured HEVC source type.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.437536', '2026-10-08 05:03:41.437537');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('54781c71-bf80-4245-8e93-8a003e6f9f92', 'Build the HEVC player test URL', 'Combine the configured HEVC source URL, configured HEVC URL type, selected codec player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete HEVC player test URL should be generated.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.440949', '2026-10-08 05:03:41.440950');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d3ddcaf5-6dcf-4749-94c7-623d6e639b10', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated HEVC player test URL>"}}.', 'The HEVC player URL should be stored successfully in PersistentStore.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.441175', '2026-10-08 05:03:41.441176');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7a777585-b29f-445d-bc63-f431c61f78a6', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.441401', '2026-10-08 05:03:41.441401');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8f3219e0-fd3c-4ecb-aff8-8cd94a9ef225', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.441586', '2026-10-08 05:03:41.441586');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('57ee0f07-0084-4dac-b6bc-8dee79656ef1', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.441839', '2026-10-08 05:03:41.441839');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d6ac58a2-8d59-412b-a8a0-06285493ab2b', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.442678', '2026-10-08 05:03:41.442679');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b429e664-730b-4d99-9872-165319f1477a', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.442940', '2026-10-08 05:03:41.442941');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d0cbb76c-1680-4818-be28-0d457c091988', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.443787', '2026-10-08 05:03:41.443788');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fcc2ab81-dc87-4bb4-9bf6-8c35df42ff00', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.445274', '2026-10-08 05:03:41.445275');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('447d6e29-0a51-4779-b469-69bb3627d510', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.446158', '2026-10-08 05:03:41.446159');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('93a89db6-a516-4b3b-9c7a-39e9d338af10', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.447056', '2026-10-08 05:03:41.447057');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2f82a974-5452-45b1-b315-ce1b1378c4b9', 'Calculate time to HEVC playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.447924', '2026-10-08 05:03:41.447925');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1d230d7c-848e-4cf7-a7a4-1da222e52bc7', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to HEVC playback should be within the configured threshold; otherwise the test should fail.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.449245', '2026-10-08 05:03:41.449246');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('baf676a8-e2e8-4e50-9803-c82f7ece0757', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.449575', '2026-10-08 05:03:41.449576');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ea98df5d-bf99-487b-a160-e5c2874bacaa', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.450662', '2026-10-08 05:03:41.450663');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('14b7e1bf-297d-4ff6-ada9-c374890c596e', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', '81a434a5-ad2c-4c39-8824-157d68db5db9', '2026-10-08 05:03:41.450871', '2026-10-08 05:03:41.450871');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4ad2be16-622c-4bd9-9c5e-6c79b85b7b1a', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'e99eeac8-4420-452e-bde1-ef988b827dd1', '2026-10-05 08:28:36.885544', '2026-10-05 08:28:36.885569');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('eca39dbf-48e6-413b-a9ce-0d809549cf54', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('176f74a5-8c88-4666-acf1-8c3a7161141c', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7b816738-8671-4d81-981c-dfefa673c328', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c4276943-5f8e-47ed-b312-eb7a80abece6', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'e99eeac8-4420-452e-bde1-ef988b827dd1', '2026-10-05 08:28:36.890569', '2026-10-05 08:28:36.890572');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f6f04784-c1be-4cc7-a8b4-ccecdd926802', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'e99eeac8-4420-452e-bde1-ef988b827dd1', '2026-10-05 08:28:36.891671', '2026-10-05 08:28:36.891674');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('92ac8cb2-602a-473e-b818-61e5a2c61fe2', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('df4ed5c7-39f6-4beb-ab83-9b7c99e8951f', 'Subscribe to download status events', 'Register a listener for application download status events using: {"jsonrpc": "2.0", "id": 2, "method": "org.rdk.DownloadManager.1.register", "params": {"event": "onAppDownloadStatus", "id": "client.events.1" }}.', 'The download status event subscription should be registered successfully.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.834426', '2026-10-07 07:59:08.834427');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9a5d7019-8c5f-44fe-9235-f2cd7d400303', 'Start the application download', 'Clear the event buffer and start downloading the configured large validation application package.', 'The download request should return success and provide a download identifier.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.835317', '2026-10-07 07:59:08.835318');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('18409902-fc86-4943-961e-1a2e42e27c5c', 'Verify download identifier uniqueness', 'Compare the returned download identifier with all identifiers recorded during the test and store it when it has not been used previously.', 'The download identifier should be unique and should be added to the recorded identifier set.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.836127', '2026-10-07 07:59:08.836128');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d0b651e2-9f0a-4e14-a1df-a8d20b636538', 'Poll download progress', 'Query download progress using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.progress","params":{"downloadId":"<download_id>"}}. Poll for up to 30 checks until progress becomes greater than zero.', 'The progress query should return successfully and should report a value greater than zero before cancellation.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.837007', '2026-10-07 07:59:08.837008');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('426b5845-5b22-4f27-8976-1b4af075e19b', 'Cancel the in-progress download', 'Cancel the download using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.cancel","params":{"downloadId":"<download_id>"}}.', 'The cancellation request should return success while the download is between 0 and 100 percent complete.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.837840', '2026-10-07 07:59:08.837841');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('243591d2-e993-4ef1-8c25-0273feb9e93a', 'Validate the cancellation event', 'Read the download event buffer for up to 120 seconds until an onAppDownloadStatus event containing DOWNLOAD_FAILURE is received. Parse the events download status and extract its download identifier and file locator.', 'A cancellation event should be received, its identifier should match the cancelled download, and its file locator should be non-empty.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.839327', '2026-10-07 07:59:08.839328');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9a0832e3-fc57-454a-ae31-5d9ee00b4316', 'Attempt immediate installation from the cancelled file locator', 'Submit an installation request for application com.rdkcentral.google using the file locator returned in the cancellation event.', 'The installation request should fail because the file locator belongs to the cancelled download.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.840209', '2026-10-07 07:59:08.840210');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('823abb47-985b-4a5e-b5fc-ca03956db733', 'Repeat the cancellation and installation validation', 'Repeat the download, uniqueness check, progress polling, cancellation, cancellation-event validation, and immediate installation attempt for the configured application manager test count.', 'The complete validation block should execute for every configured iteration, and each iteration should confirm expected installation failure after cancellation.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.841165', '2026-10-07 07:59:08.841166');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ecef294a-214f-48de-8a6e-7df08fb418f6', 'Disconnect the event listener and test module', 'Disconnect the download event listener and unload the rdkv_stability test module after all iterations complete.', 'The event listener and test module should be disconnected and unloaded cleanly.', '8f37cae6-c6e7-4cea-aaa8-7c2ee494fca3', '2026-10-07 07:59:08.841997', '2026-10-07 07:59:08.841998');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('190536e0-1ecc-4e10-a4c1-b4b537f55c0f', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', 'e6008b33-bae5-49e9-b232-3b9a4637db37', '2026-09-08 07:15:35.312098', '2026-09-08 07:15:35.312101');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cd8af554-1db6-4cc5-84da-e9ef19e303f8', 'Test Step 2', 'The application starts playing a Widevine DRM-protected HLS HEVC AAC stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The HLS HEVC AAC stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', 'e6008b33-bae5-49e9-b232-3b9a4637db37', '2026-09-08 07:15:35.313048', '2026-09-08 07:15:35.313050');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ddaf0fdf-4a7b-400a-b15e-19397abb4a9d', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', 'e6008b33-bae5-49e9-b232-3b9a4637db37', '2026-09-08 07:15:35.313993', '2026-09-08 07:15:35.313994');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ef30143-03d2-4067-ba2c-d4073405fcb9', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', 'e6008b33-bae5-49e9-b232-3b9a4637db37', '2026-09-08 07:15:35.314235', '2026-09-08 07:15:35.314236');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fef7da56-9f38-448b-be4b-de293bef8d8e', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', 'e6008b33-bae5-49e9-b232-3b9a4637db37', '2026-09-08 07:15:35.314511', '2026-09-08 07:15:35.314513');
