INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1dec1324-c12f-4146-ab88-4cf21a4a91a5', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '39946711-aa32-4663-9131-1b6afb93e183', '2026-09-09 08:56:39.058139', '2026-09-09 08:56:39.058141');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('db4e0d72-705a-4a71-b035-7bf112050fe9', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2e4a536a-044b-4fb6-b205-e177e9455af6', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', '5e58d44c-7729-44c8-8a90-b2f741baa305', '2026-10-06 10:33:34.954403', '2026-10-06 10:33:34.954404');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9ac7d256-ce95-49de-ba5c-f5c4a1196d83', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6df672d3-b365-407a-a910-b05e059187cd', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c3536896-ea00-4297-8c58-2af9c3b3a54f', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb6bb530-8c01-4848-a057-7a59ed72a453', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', '5e58d44c-7729-44c8-8a90-b2f741baa305', '2026-10-06 10:33:34.959220', '2026-10-06 10:33:34.959221');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('859e5df3-8198-4f27-9946-015e64375060', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', '5e58d44c-7729-44c8-8a90-b2f741baa305', '2026-10-06 10:33:34.960096', '2026-10-06 10:33:34.960097');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('1e95c405-4e99-4e49-be3c-5d8affbb1ca0', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d1db8e96-807a-4721-9ddb-b67c3e590893', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.006136', '2026-10-08 04:42:43.006137');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d44b17b9-e311-4ca2-b14b-3266637ec11e', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.006971', '2026-10-08 04:42:43.006972');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ae8c4795-4e9a-402a-8f45-9bc53702b4a7', 'Build the 4K HLS player test URL', 'Combine the configured 4K HLS source URL, hls URL type, selected HEVC HLS codec/player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete 4K HLS player test URL should be generated.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.007163', '2026-10-08 04:42:43.007164');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a1a1d813-3d2c-4f13-bb96-9fcc5d4cf237', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated 4K HLS player test URL>"}}.', 'The 4K HLS player URL should be stored successfully in PersistentStore.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.008054', '2026-10-08 04:42:43.008055');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a5b8e35c-4cca-4d4a-9abf-245a044cc7d2', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.008947', '2026-10-08 04:42:43.008948');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('24ebd65a-f032-461f-a04e-88e496995161', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.009769', '2026-10-08 04:42:43.009769');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e71cda69-ac8a-40a3-9446-6e3f26a1b078', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.010629', '2026-10-08 04:42:43.010630');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('953c5d37-fcc9-45ec-a2c6-332e59fa8b36', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.011545', '2026-10-08 04:42:43.011546');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e5404c1f-a71a-4739-aa8a-6b8f32a8c66d', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.012393', '2026-10-08 04:42:43.012394');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8fed658f-78cb-4d20-84b0-8e20e57f03d4', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.013319', '2026-10-08 04:42:43.013320');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('202d1ec8-e2d4-4a31-8c86-296d7e859da1', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.014164', '2026-10-08 04:42:43.014165');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8b7bb841-03bf-4b1c-8739-fac5119f701f', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.015001', '2026-10-08 04:42:43.015002');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('899ceac4-d213-4b32-8fd1-07acaf391b35', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.015806', '2026-10-08 04:42:43.015807');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6ba618cf-154c-4626-904b-19f8449488bf', 'Calculate time to video playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.015995', '2026-10-08 04:42:43.015996');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('77a0d74d-b5ac-4743-9e0f-a989779ea11e', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to 4K HLS video playback should be within the configured threshold; otherwise the test should fail.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.016799', '2026-10-08 04:42:43.016800');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('e2ad1a19-c725-4cc1-b254-c00167061a5e', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.016985', '2026-10-08 04:42:43.016985');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('426dce5b-4152-4433-b7b4-acfca54c8098', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.018475', '2026-10-08 04:42:43.018476');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c91d027a-08ed-4861-9122-0aff2b382734', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'faaaa3f6-c838-45cc-9bb4-2a5b6dce7129', '2026-10-08 04:42:43.018697', '2026-10-08 04:42:43.018698');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d2cb9ea4-7313-48f2-84d2-8d65321cbef5', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', '1117c52a-95ad-44b2-b889-071cb63be407', '2026-09-08 07:08:36.828648', '2026-09-08 07:08:36.828651');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fed94900-6c34-4833-82df-f726742ca5de', 'Test Step 2', 'The application starts playing a Widevine DRM-protected HLS H264 AAC stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The HLS H264 AAC stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', '1117c52a-95ad-44b2-b889-071cb63be407', '2026-09-08 07:08:36.829753', '2026-09-08 07:08:36.829756');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('205bb539-33cc-4050-a436-47b7ca0a1639', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', '1117c52a-95ad-44b2-b889-071cb63be407', '2026-09-08 07:08:36.830766', '2026-09-08 07:08:36.830769');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('62de6197-92d8-4317-a5b7-73da606b21b8', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', '1117c52a-95ad-44b2-b889-071cb63be407', '2026-09-08 07:08:36.831848', '2026-09-08 07:08:36.831850');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('37eccc62-a6e6-4cdc-b892-aa952497dad1', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', '1117c52a-95ad-44b2-b889-071cb63be407', '2026-09-08 07:08:36.832994', '2026-09-08 07:08:36.832996');
