INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('92503134-b1be-4230-8625-a3532061d020', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.119535', '2026-10-06 17:27:38.119537');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4ac69557-e5e4-4a3c-9825-1831ff4a0227', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.121212', '2026-10-06 17:27:38.121213');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('56594abf-ec4e-4fa6-bfa7-ea6b2320e150', 'Build the AAC player test URL', 'Combine the configured AAC source URL, AAC URL type, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL. Select the player list from codec_hls_aac when the URL type is hls, from codec_dash_aac when it is dash, or from codec_mp4 for other URL types.', 'A complete AAC player test URL should be generated with the player selection matching the configured URL type.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.122243', '2026-10-06 17:27:38.122244');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('43bbbbf0-c4f4-44a0-bc76-3949df0e8c67', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated AAC player test URL>"}}.', 'The AAC player URL should be stored successfully in PersistentStore.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.124062', '2026-10-06 17:27:38.124063');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3d54483b-7e88-4486-83d5-1d1566288588', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.124411', '2026-10-06 17:27:38.124412');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7f40a86f-ee4f-419c-b9bf-0519032c2545', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.125432', '2026-10-06 17:27:38.125434');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('46226b38-6ffb-4e80-9d82-746952a12290', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.126472', '2026-10-06 17:27:38.126474');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('893fb807-ce10-4247-bcbc-3c1084d57aaa', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.126807', '2026-10-06 17:27:38.126808');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5419759c-5c60-41b4-aad5-25bf3f7108f1', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.127817', '2026-10-06 17:27:38.127818');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6798c5da-2ef1-467d-b981-af74b8e5205d', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.128711', '2026-10-06 17:27:38.128711');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('22005df4-b538-4ab3-a2fd-6aa1a121c6be', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.129650', '2026-10-06 17:27:38.129651');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d4dd6fc4-fae0-4084-a488-d4ebc63c2755', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.130492', '2026-10-06 17:27:38.130493');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('abfaf2b3-6504-4ab0-9e60-181acb65b280', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.131300', '2026-10-06 17:27:38.131301');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d64aa154-bf4a-42df-bcb0-7a2bb1832261', 'Calculate time to AAC playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.131519', '2026-10-06 17:27:38.131520');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('47a21d2b-8627-44f4-997f-8e5c5a07f328', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to AAC playback should be within the configured threshold; otherwise the test should fail.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.132408', '2026-10-06 17:27:38.132409');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('aa877f10-af87-49cf-b399-bd72f96ce5a3', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.133355', '2026-10-06 17:27:38.133356');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('44118b62-def3-4577-944c-0ba55df4412a', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.134368', '2026-10-06 17:27:38.134369');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('6bf41604-ae43-4bf7-bf8a-5adf0bc068a1', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'f7ce7460-12af-4591-b9bb-11efb698cc40', '2026-10-06 17:27:38.135232', '2026-10-06 17:27:38.135233');
