INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('52881782-6c67-4c04-b88b-58447368667e', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'c590300c-bb5b-4739-91af-be49188c60d2', '2026-10-06 10:39:42.181493', '2026-10-06 10:39:42.181494');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('dc05b44d-f5f8-417f-9da2-ae0698fa5079', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'c590300c-bb5b-4739-91af-be49188c60d2', '2026-10-06 10:39:42.182483', '2026-10-06 10:39:42.182484');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('94626062-7b70-4dad-a489-e9f7668c5d92', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4ee42dde-5cc1-4262-adfb-3b8bb7ac05d3', 'Activate the required application services', 'Query the device application service states and activate any service that is not already active: org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, and org.rdk.RDKWindowManager.', 'The required application services should be activated successfully.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.054305', '2026-10-07 08:29:35.054306');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f2e5360a-154e-4a88-9b39-5db1ced38418', 'Install the application under test', 'Download and install the configured Google application bundle for application com.rdkcentral.google without launching it.', 'The application should be installed successfully before preload validation begins.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.055879', '2026-10-07 08:29:35.055880');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('284fe7f1-9b20-4fe6-9270-e74a375bc3db', 'Preload the application', 'Request application preload using the AppManager JSON-RPC method: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.preloadApp","params":{"appId":"com.rdkcentral.google"}}.', 'The preload request should return success.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.056707', '2026-10-07 08:29:35.056708');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('447ca507-b9c6-42c0-8d4f-f76f01727243', 'Verify the preloaded lifecycle state', 'Query loaded applications using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps","params":{}}. Confirm that the entry for com.rdkcentral.google has both lifecycleState and targetLifecycleState set to APP_STATE_PAUSED.', 'The application should be present with APP_STATE_PAUSED as both its current and target lifecycle state.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.057477', '2026-10-07 08:29:35.057478');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('82fb8e9a-212a-478e-9a84-c3c3c5e18a99', 'Launch the preloaded application', 'Submit a launch request for com.rdkcentral.google to activate the preloaded application.', 'The launch request should return success.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.058262', '2026-10-07 08:29:35.058263');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3654dbb1-495e-4e9d-be57-b37c7a7576bb', 'Verify the active lifecycle state', 'Query loaded applications again using: {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps","params":{}}. Confirm that the application entry has lifecycleState set to APP_STATE_ACTIVE.', 'The application should transition to and remain in the APP_STATE_ACTIVE lifecycle state.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.059103', '2026-10-07 08:29:35.059104');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('63bcc7bc-8dcc-441d-a170-2c76412a3ebc', 'Terminate the application', 'Terminate com.rdkcentral.google using its application identifier.', 'The termination request should return success.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.059977', '2026-10-07 08:29:35.059978');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9405d08a-e1dd-4d79-bb0d-a9ccbac6c7c4', 'Verify that no orphaned instance remains', 'Read the loaded-application list after termination and verify that com.rdkcentral.google is absent.', 'The application should not appear in the loaded-application list, and no orphaned instance should remain.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.060819', '2026-10-07 08:29:35.060819');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('aaf8190a-9857-4705-a491-3a8ab49c118a', 'Validate resource usage', 'Request resource-usage validation after the application is terminated.', 'Resource usage should be reported within the expected limit and should not return an error.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.062356', '2026-10-07 08:29:35.062357');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bcc9835e-c230-4630-8eac-c856c11cc1bc', 'Repeat the preload and lifecycle validation', 'Repeat the preload request, paused-state verification, launch request, active-state verification, termination, orphan check, and resource-usage validation for the configured application manager test count.', 'The complete lifecycle block should execute for every configured iteration, and any failed state, termination, orphan, or resource check should mark the corresponding iteration unsuccessful.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.063187', '2026-10-07 08:29:35.063188');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3952a344-ece9-4bc9-9471-64421ad05bc2', 'Complete the test module', 'Unload the rdkv_stability test module after all iterations complete.', 'The test module should be unloaded cleanly and the final test status should reflect the observed results.', '4269b9f1-5986-423a-a82c-708737bf514b', '2026-10-07 08:29:35.064065', '2026-10-07 08:29:35.064065');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2b8d60ab-4931-4088-8c0a-8473c2dda493', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', '8a58d511-077f-4dd4-9d2b-5482297bd09a', '2026-09-08 07:14:23.044814', '2026-09-08 07:14:23.044817');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7d7d4043-ba24-4ff5-97f8-b4868df01bc5', 'Test Step 2', 'The application starts playing a Widevine DRM-protected AAC DASH stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The DASH AAC stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', '8a58d511-077f-4dd4-9d2b-5482297bd09a', '2026-09-08 07:14:23.045771', '2026-09-08 07:14:23.045774');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('779fedb5-2474-4f12-9806-3d7bf8c36de8', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', '8a58d511-077f-4dd4-9d2b-5482297bd09a', '2026-09-08 07:14:23.046677', '2026-09-08 07:14:23.046678');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8a41bc86-c7e4-4776-9bbc-c1010427c649', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', '8a58d511-077f-4dd4-9d2b-5482297bd09a', '2026-09-08 07:14:23.047558', '2026-09-08 07:14:23.047559');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4c6e5f08-8742-479a-b0b8-745fe12c191c', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', '8a58d511-077f-4dd4-9d2b-5482297bd09a', '2026-09-08 07:14:23.048425', '2026-09-08 07:14:23.048427');
