INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7c9457f8-7387-40b1-a309-9e20dfccc4a8', 'Load the first stream (SDR) and capture media events.', 'The player loads the first URL from the list and starts playback of the SDR stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the SDR playback.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-08 07:21:19.960705', '2026-09-08 07:21:19.960707');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('2f557871-bc78-493c-b905-05b90fe63fb9', 'Validate observed events for the first playback and record intermediate result.', 'If the SDR stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the SDR playback.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-08 07:21:19.961606', '2026-09-08 07:21:19.961608');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('955242e3-a6cd-49bb-92b7-ad8e0d60996d', 'Clear the browser, load the second stream (HDR) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the HDR stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the HDR stream loads and media events are captured.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-08 07:21:19.961841', '2026-09-08 07:21:19.961843');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('41a1ae8c-df43-402c-a630-32fad583044c', 'Validate observed events for the second playback and record intermediate result.', 'If the HDR stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the second stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the HDR playback.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-08 07:21:19.962073', '2026-09-08 07:21:19.962074');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('98948422-8a1c-45fe-9742-aa90646ba7cc', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the SDR and HDR playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', '80eb029c-9f70-4dd7-a616-6a5ef9b31686', '2026-09-08 07:21:19.962302', '2026-09-08 07:21:19.962303');
