INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('7de64f9a-9075-4c9e-82ae-aa2d4908c7b0', 'Set playback operations for given stream.', 'Configure the close (30) operation for stream: The video player will play the stream for 30 seconds and then close the player.', 'Ensure that the playback operations are set as specified for given stream.', 'bfcc0045-651b-4622-b849-868df0b52219', '2026-09-09 08:55:01.913131', '2026-09-09 08:55:01.913133');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3bf3a658-ab2b-42fe-a6a2-cf4bf69c7897', 'Store the launch URL in PersistentStore.', 'Construct and store the launch URL in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('691da34b-4d86-49ed-90bf-1a80db59684b', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('30c98b95-f249-4e7d-84e0-625624da24d8', 'Check loaded apps and verify app presence.', 'Check whether the app is listed in loaded apps using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5f9ea170-b13d-435b-93b1-3fc03ff15689', 'Run video playback and capture the FPS along with media events.', 'The player opens the stream and starts playback. A **play** event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions. The FPS values are calculated during the playback of the stream, and the average FPS is calculated based on the values obtained. The player closes automatically after the configured duration.', 'Ensure that the average fps and video playback events are captured for the configured duration.', 'bfcc0045-651b-4622-b849-868df0b52219', '2026-09-09 08:55:01.918202', '2026-09-09 08:55:01.918204');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('56688909-9cae-4d51-bb18-ca2d694942fa', 'Validate the observed events for the video playback operation, confirm that the average FPS falls within the expected range, and update the test result accordingly.', 'If playback starts successfully, the video position advances continuously throughout the configured duration without stalls or interruptions, and the average FPS falls within the expected range, the app reports SUCCESS, otherwise FAILURE. The test result is updated as SUCCESS or FAILURE based on event validation, FPS validation, and proc check status.', 'Ensure that the test result is updated as SUCCESS or FAILURE based on the video playback event validation, FPS validation, and proc check status.', 'bfcc0045-651b-4622-b849-868df0b52219', '2026-09-09 08:55:01.919102', '2026-09-09 08:55:01.919104');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8a857122-176b-44fd-8255-fb1d40aa8ce5', 'Terminate the app and restore test environment.', 'Terminate the test app through AppManager using the following request:
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('74e5ed6b-4d63-4773-ad73-4a224373832d', 'Check the required plugin states', 'Query DeviceInfo and org.rdk.PersistentStore with {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@DeviceInfo"} and {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@org.rdk.PersistentStore"}.', 'Each required plugin should return the activated state.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.612501', '2026-10-08 05:00:25.612502');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('47de733d-5faa-4c4c-b1af-b7c8a90dd2c7', 'Activate unavailable required plugins', 'If either required plugin is not activated, request activation with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}, then query its status again.', 'Each required plugin should report activated after the activation request.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.613352', '2026-10-08 05:00:25.613353');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('9598f731-f213-4d25-9e49-918c3de377ab', 'Build the direct WebM player test URL', 'Combine the configured direct WebM source URL, webm URL type, selected codec_webm player, execution identifiers, logging information, pause and play operations, and autotest: "true" into the unified player test URL.', 'A complete direct WebM player test URL should be generated.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.614214', '2026-10-08 05:00:25.614215');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('adb82f5f-b173-40bb-b6a7-c4ce22d7e248', 'Store the player URL in PersistentStore', 'Set the MVS lightningURL value with {"jsonrpc":"2.0","id":1,"method":"org.rdk.PersistentStore.setValue","params":{"namespace":"MVS","key":"lightningURL","value":"<generated direct WebM player test URL>"}}.', 'The direct WebM player URL should be stored successfully in PersistentStore.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.614423', '2026-10-08 05:00:25.614424');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d36176e6-2c23-454d-9081-d9c655df3988', 'Check whether the unified player is installed', 'Request the installed package list with org.rdk.AppPackageManager.1.listPackages and inspect the returned installed package IDs for the derived application ID.', 'The application should be identified as installed, or the flow should proceed to download and install it.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.614609', '2026-10-08 05:00:25.614609');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('958d5828-c157-421c-8fdd-74fa671dde41', 'Check application-management plugin availability', 'Query org.rdk.DownloadManager, org.rdk.AppPackageManager, and org.rdk.AppManager using {"jsonrpc":"2.0","id":1,"method":"Controller.1.status@<plugin>"}. Activate any unavailable plugin with {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}}.', 'All application-management plugins should report the activated state before package installation.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.615431', '2026-10-08 05:00:25.615432');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ee198817-4a46-4e3d-8085-d09b94ec0d88', 'Download the unified player bundle', 'Request the configured application bundle with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<configured application download URL>/<bundle name>"}}.', 'The application bundle should download successfully and return package details for installation.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.615629', '2026-10-08 05:00:25.615630');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('42eb12ea-d0a3-40d4-a405-bddfd9921ec4', 'Install the unified player bundle', 'Install the downloaded package with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<application ID>","version":"0.1.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<configured locator><download result>"}}.', 'The bundle should install successfully.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.615821', '2026-10-08 05:00:25.615822');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('c6097eef-e4df-477c-8820-90aa8d5fcbc6', 'Verify the installed application', 'Query org.rdk.AppPackageManager.1.listPackages again and check that the derived application ID is present in the installed package list.', 'The application ID should appear in the installed package list.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.616034', '2026-10-08 05:00:25.616035');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('3aeed7c3-44d7-47a4-b8ef-d7f2a9e87b7a', 'Launch the unified player', 'Launch the installed application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<application ID>","intent":"","launchArgs":""}}.', 'The launch request should return success.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.616232', '2026-10-08 05:00:25.616233');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('39a22611-ff5b-42a3-8349-90052e962d8a', 'Verify the application is active', 'Query loaded applications with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.getLoadedApps"} and locate the application ID with lifecycle state APP_STATE_ACTIVE.', 'The unified player should appear as an active loaded application.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.616432', '2026-10-08 05:00:25.616433');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bb8c6ab9-bbf4-44c1-b767-7adba60ce1a4', 'Capture the Video Player Playing timestamp', 'Monitor the REST API application log until an entry containing Video Player Playing is received, then extract its timestamp.', 'A valid Video Player Playing timestamp should be captured.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.617393', '2026-10-08 05:00:25.617394');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a5a22c66-7cfd-4c7b-80d4-220eaf2f507a', 'Capture the WPE load committed timestamp', 'Obtain the application storage path with grep DEFAULT_APP_STORAGE_PATH /etc/device.properties | cut -d''='' -f2, then read the latest timestamp with grep -i ''wpe load committed'' <application log> | tail -n 1 | cut -d'' '' -f2 | sed ''s/:$//''.', 'A valid WPE load committed timestamp should be captured from the application log.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.618226', '2026-10-08 05:00:25.618226');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('34110225-312b-440c-abb2-8d4d960a3274', 'Calculate time to direct WebM playback', 'Convert both timestamps to milliseconds and calculate Video Player Playing - WPE load committed.', 'The elapsed time should be calculated as a positive millisecond value.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.618434', '2026-10-08 05:00:25.618435');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('a40bbc4f-3010-4397-8181-af17519efda3', 'Validate the playback threshold', 'Read VIDEO_PLAYBACK_THRESHOLD_VALUE and THRESHOLD_OFFSET from the device configuration and verify that 0 < elapsed time < VIDEO_PLAYBACK_THRESHOLD_VALUE + THRESHOLD_OFFSET.', 'The time to direct WebM playback should be within the configured threshold; otherwise the test should fail.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.618609', '2026-10-08 05:00:25.618610');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('4c6d138b-3c71-437c-83ac-c403b788b6d3', 'Terminate the unified player', 'Terminate the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.1.terminateApp","params":{"appId":"<application ID>"}}.', 'The unified player should terminate successfully.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.618789', '2026-10-08 05:00:25.618790');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('995fc408-7c20-457e-8349-17b356d1aa60', 'Restore modified plugin states', 'If the test changed plugin states, restore DeviceInfo and org.rdk.PersistentStore to their original states with the corresponding Controller.1.activate or Controller.1.deactivate request.', 'The plugins should be restored to their states before test execution.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.619568', '2026-10-08 05:00:25.619569');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('d86d881c-0bef-4d71-ba10-6dbbe82097f6', 'Record the execution summary and unload the module', 'Record the threshold values, captured timestamps, and measured time-to-playback result, then unload the rdkv_performance module.', 'The execution summary should be available and the test module should unload successfully.', 'ecc96887-b43e-4865-9128-c6b97577c20a', '2026-10-08 05:00:25.620335', '2026-10-08 05:00:25.620336');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ac461e09-8163-4452-9df2-09fd8159aec9', 'Test Step 1', 'Launch webkit instance with video test app with the video src url and duration for close', 'Successfully launched the webkit instance with video test app with the video src url and close interval', '38669f5c-afc3-4b63-8467-f0a067620d58', '2026-09-08 07:13:07.497314', '2026-09-08 07:13:07.497316');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fd58e0cd-55df-4b67-8038-4be84c458973', 'Test Step 2', 'The application starts playing a Widevine DRM-protected HEVC AAC DASH stream, where playback begins with clear content using 9 skip byte blocks (clear lead) followed by encrypted content using 1 crypt byte block. Video playback continues without interruption, and the player closes after the configured duration.', 'The DASH HEVC AAC stream is played smoothly with initial clear content using 9 skip byte blocks (clear lead), followed by encrypted content using 1 crypt byte block with Widevine DRM, and the player is closed after the provided duration.', '38669f5c-afc3-4b63-8467-f0a067620d58', '2026-09-08 07:13:07.497667', '2026-09-08 07:13:07.497669');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fa7b7fb2-e9d2-4348-81ed-11f805d27830', 'Test Step 3', 'If the video plays as expected with a combination of clear (9 skip byte blocks) and encrypted (1 crypt byte block) content and playback reaches the ended state, the result is marked as SUCCESS; otherwise, it is marked as FAILURE.', 'App gives the validation result as SUCCESS or else FAILURE based on events captured', '38669f5c-afc3-4b63-8467-f0a067620d58', '2026-09-08 07:13:07.497952', '2026-09-08 07:13:07.497954');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('65a62e0d-7256-4b9f-b47f-1663230ced38', 'Test Step 4', 'Update the test script result as SUCCESS/FAILURE based on event validation result and proc check status (if applicable)', 'Successfully updated the test script result as SUCCESS/FAILURE based on the validation results', '38669f5c-afc3-4b63-8467-f0a067620d58', '2026-09-08 07:13:07.498913', '2026-09-08 07:13:07.498914');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('36d82a15-5d8a-4eca-9f0c-3526ce31d0a3', 'Post Condition', 'Revert all the pre-requisites to the default values', 'All the pre-requisites are successfully reverted to default values', '38669f5c-afc3-4b63-8467-f0a067620d58', '2026-09-08 07:13:07.499846', '2026-09-08 07:13:07.499848');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('db359b88-fcac-40bd-a47e-921f9352f65f', 'Load the performance test module', 'Load the RDKV performance test module and configure the testcase for RDKV_CERT_PVS_AppManager_Launch_After_Uninstall.', 'The performance test module should load successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.844534', '2026-09-08 06:26:59.844539');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('87823848-dc50-4ca2-9598-2f13d558118a', 'Activate the required plugins when necessary', 'If any required plugin is not activated, activate it with the following JSON-RPC request for each affected callsign: {"jsonrpc":"2.0","id":1,"method":"Controller.1.activate","params":{"callsign":"<plugin>"}} where <plugin> is one of org.rdk.DownloadManager, org.rdk.AppPackageManager, org.rdk.AppManager, or org.rdk.RDKWindowManager.', 'Each required plugin should become activated successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.845756', '2026-09-08 06:26:59.845760');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('f3a5eaa7-ed5a-4cd3-a00c-eb12e848d3da', 'Check whether the application is installed', 'Query the installed package list with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"}. If the derived application ID is present, retain the installed application; otherwise continue with download and installation.', 'The installed-package query should complete successfully, and the application installation state should be determined.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.847016', '2026-09-08 06:26:59.847021');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('814bd3fd-9cdf-4dde-8da6-73413c2e7ed5', 'Download the application bundle when required', 'When the application is not installed, request its download using org.rdk.DownloadManager.1.download with {"jsonrpc":"2.0","id":1,"method":"org.rdk.DownloadManager.1.download","params":{"url":"<app_download_url>/<google_bundle>"}}.', 'The application bundle should download successfully and return a package reference.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.848315', '2026-09-08 06:26:59.848320');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('838e94ba-37e0-457f-b27b-1a06e0b33960', 'Install the downloaded application bundle', 'Use the configured package file locator and returned package reference to install the application with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.install","params":{"packageId":"<app_id>","version":"0.2.0","additionalMetadata":[{"name":"type","value":"native/dac-app"}],"fileLocator":"<PACKAGEMANAGER_FILE_LOCATOR><package_reference>"}}.', 'The application should install successfully.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.850445', '2026-09-08 06:26:59.850449');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5ca2d12b-b23a-4603-8fda-0402725eb2fe', 'Verify the application installation', 'Query the installed package list again with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.1.listPackages"} and confirm that the derived application ID is listed.', 'The application ID should appear in the installed package list.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.851705', '2026-09-08 06:26:59.851710');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('8e53efba-56cd-4ce8-a1ad-c9d74dcfbafc', 'Uninstall the application', 'Uninstall the application using org.rdk.AppPackageManager.uninstall with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppPackageManager.uninstall","params":{"packageId":"<app_id>"}}.', 'The uninstall request should return success.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.852212', '2026-09-08 06:26:59.852216');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('5f48d6ab-7f3d-40bf-9028-e3adc6de5de2', 'Wait for uninstall completion', 'Wait 5 seconds after the successful uninstall request before attempting to launch the application.', 'The device should have sufficient time to complete removal of the application package.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.852735', '2026-09-08 06:26:59.852739');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('cbdcd125-7605-4901-8eca-a4b3e4583b06', 'Attempt to launch the uninstalled application', 'Send a launch request using org.rdk.AppManager.launchApp with {"jsonrpc":"2.0","id":1,"method":"org.rdk.AppManager.launchApp","params":{"appId":"<app_id>","intent":"","launchArgs":""}}.', 'The launch request should be rejected and should not return success because the application was uninstalled.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.853944', '2026-09-08 06:26:59.853949');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('44d134f9-a606-4cbb-a17a-1049c9e3c918', 'Record the negative launch result', 'Mark the test successful when the launch result is not SUCCESS; mark it unsuccessful if the uninstalled application launches successfully.', 'The final testcase result should be successful only when AppManager prevents launching the removed application.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.855140', '2026-09-08 06:26:59.855143');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('aa0ce2cb-bc95-4ffe-9ade-af8be9c3e13c', 'Unload the performance test module', 'Unload the RDKV performance test module after completing the installation, uninstall, and launch validation.', 'The performance test module should unload cleanly.', '0da08d26-7b33-40fe-9229-956a12a48d20', '2026-09-08 06:26:59.865289', '2026-09-08 06:26:59.865293');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('72f1c8ab-9959-4f8b-8c6b-2bd503c8cffc', 'Set playback operations for both streams.', 'Configure the close (30) operations for each stream: the video player will play each stream for 30 seconds.', 'Ensure playback operations are set as specified for both streams.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-08 07:20:36.440987', '2026-09-08 07:20:36.440988');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb17dd2d-4a80-486b-8872-28ea04c605c4', 'Store both stream URLs as a list in PersistentStore.', 'Construct and store both stream URLs as an ordered list in PersistentStore for AppManager launch.
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('ac9139d3-b327-4154-93d4-1c55874ff2b2', 'Launch the app through AppManager.', 'Launch the test app through AppManager using the following request:
