INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('fb5ff538-635a-45e3-9c22-fd0292e4be61', 'Load the first stream (DASH HEVC) and capture media events.', 'The player loads the first URL from the list and starts playback of the DASH HEVC stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the media events are captured for the DASH HEVC playback.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-08 07:20:36.442627', '2026-09-08 07:20:36.442629');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('53c8b50c-679f-475a-940c-a72beecc7c1f', 'Validate observed events for the first playback and record intermediate result.', 'If the DASH HEVC stream plays back successfully and the video position advances continuously throughout the configured duration without stalls or interruptions, the app reports SUCCESS, otherwise FAILURE. The intermediate result is recorded for the first stream.', 'Ensure that the intermediate result is recorded as SUCCESS or FAILURE for the DASH HEVC playback.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-08 07:20:36.442878', '2026-09-08 07:20:36.442879');
INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('bad9d5b8-f61d-4c13-88a2-f866d9b3772a', 'Clear the browser, load the second stream (DASH AV1) and capture media events.', 'The browser is cleared after the first playback. The player then loads the second URL from the list and starts playback of the DASH AV1 stream. A play event confirms that the video has started. The video position is monitored during playback to confirm the content is advancing continuously without stalls or interruptions for the configured duration.', 'Ensure that the browser is cleared and the DASH AV1 stream loads and media events are captured.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-08 07:20:36.443130', '2026-09-08 07:20:36.443131');
