INSERT INTO test_step (id, step_name, step_description, expected_result, script_id, created_date, updated_at) VALUES ('b4a21ad5-1ad6-4459-a1e2-33c18d5a2efb', 'Get successive playback result and set the final test result.', 'The successive playback result is computed as a summary of both individual playback results. The final test result is updated as SUCCESS only if both the DASH HEVC and DASH AV1 playbacks succeed, otherwise FAILURE.', 'Ensure that the consolidated result correctly reflects the outcome of both playbacks.', 'fc56f1b9-31d1-493b-ad07-63db55f22410', '2026-09-08 07:20:36.445117', '2026-09-08 07:20:36.445119');
